WITH payload AS (SELECT $archive_payload$[{"id":"f0e763cd-2fd2-5501-9a3c-41959993afd7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تصنيع وترويج املسكر -إقرار بتصنيع العرق -تعزير بالسجن واجللد واإلبعاد .","document_number":"34202301","case_number":"33593735","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وبرفقها القرار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/30","year":"1434","subject":"مسكر -تصنيع وترويج املسكر -إقرار بتصنيع العرق -تعزير بالسجن واجللد واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34202301:‬تاريخه‪1434/04/30 :‬هـ‬\n                          ‫رقم الدعوى‪33593735:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34202301:‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n       ‫مســكر ‪ -‬تصنيــع وترويــج املســكر ‪ -‬إقــرار بتصنيــع العــرق ‪ -‬تعزيــر‬\n                                                        ‫بالســجن واجللــد واإلبعــاد ‪.‬‬\n\n\n\n\n                                  ‫ما أشار له القاضي مبا جاء يف تسبيب احلكم ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعى عليهما (رجل وامــرأة مقيمني) بتصنيع‬\n       ‫وترويــج اخلمــور املصنعــة محليــا (العــرق) بعــد ورود بــاغ مفــاده توفــر‬\n       ‫معلومــات عــن قيــام املدعــى عليــه األول بترويــج اخلمــور (العــرق) املصنعــة‬\n       ‫محليــا وطلــب املدعــي العــام احلكــم بإثبــات مــا أســند إليهمــا واحلكــم‬\n       ‫عليهمــا بعقوبــة تعزيريــه لقــاء ذلــك وبعــرض دعــوى املدعــي العــام علــى‬\n       ‫املدعــى عليــه وهــو يحســن التحــدث بالعربيــة صــادق علــى دعــوى تصنيــع‬\n       ‫اخلمــور‪ ،‬ودفــع بــأن املصنــع ال يعــود إليــه وإمنــا يعــود إلــى شــخص ال يعرفــه‬\n       ‫‪ ،‬وأنكــر دعــوى ترويــج وبيــع اخلمــور‪ ،‬وبعــرض الدعــوى علــى املدعــى‬\n       ‫عليهــا الثانيــة وهــي حتســن التحــدث بالعربيــة أنكــرت دعــوى املدعــي‬\n       ‫العــام ودفعــت بأنهــا تعمــل يف مصنــع اخلمــر عاملــة نظافــة‪ ،‬براتــب مــن‬\n       ‫املدعــى عليــه األول وال عالقــة لهــا بتصنيــع أو بيــع اخلمــور‪ ،‬كمــا جــرى‬\n       ‫االطــاع علــى التقريــر الكيمــاوي املتضمــن إيجابيــة املــادة الســائلة‬\n\n‫‪307‬‬\n\f‫للكحــول االثيلــي ‪ -‬ثبتــت إدانــة املدعــى عليــه بتصنيــع اخلمــور وتوجــه‬\n‫الشــبهة القويــة جتاهــه بترويــج اخلمــور ومت احلكــم بتعزيــره لقــاء ذلــك‬\n‫بســجنه ســنة وجلــده مائــة وخمســن جلــده مفرقــة علــى ثــاث دفعــات مــع‬\n‫التوصيــة بإبعــاده مــن البــاد‪ ،‬كمــا ثبتــت إدانــة املدعــى عليهــا بالعمــل‬\n‫يف مصنــع خمــور يف مجــال النظافــة وتوجــه الشــبهة القويــة جتاههــا‬\n‫بترويــج وتصنيــع اخلمــور ومت احلكــم بتعزيرهــا بســجنها تســعة أشــهر‬\n‫وجلدهــا خمســن جلــدة دفعــة واحــدة وبعــرض احلكــم علــى املدعــي‬\n‫العــام قــرر االعتــراض مكتفيــا بالئحــة الدعــوى أمــا املدعــى عليهمــا‬\n‫فقــد قــررا القناعــة باحلكــم وبعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                         ‫متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33593735‬وتاريــخ ‪1433/10/10‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331779513‬وتاريــخ ‪1433/10/10‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/03/22‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪......‬وادعــى علــى ‪28 ...... -1 /‬ســنة اثيوبــي‬\n‫اجلنســية (ال يحمــل مــا يثبــت هويتــه ) موقــوف مبوجــب مذكــرة رقــم‬\n                                                   ‫‪ 1431‬يف ‪1433/7/26‬ه ـ‬\n‫‪ 21......-2‬ســنه اثيوبيــة اجلنســية (ال حتمــل مــا يثبــت هويتهــا ) موقوفــه‬\n                          ‫مبذكــرة توقيــف رقــم ‪ 200‬يف ‪1433/7/11‬ه ـ‬\n‫بتاريــخ ‪1433/7/19‬ه ـ ورد ملركــز شــرطة ‪......‬محضــر هيئــة ‪......‬رقــم‬\n\n                                                                                    ‫‪308‬‬\n\f      ‫‪ 21/201‬املتضمــن توفــر معلومــات عــن شــخص يدعــى ‪(...... /‬ال يحمــل‬\n      ‫مــا يثبــت هويتــه ) يقــوم بترويــج اخلمــور املصنعــة محليــا فتــم االتفــاق معــه‬\n      ‫عــن طريــق احــد املصــادر علــى شــراء كرتــون يحــوي إثنــاء عشــر قــارورة‬\n      ‫ســعة الواحــد منهــا لتــر ونصــف مببلــغ خمســمائة ريــال ويف املــكان‬\n      ‫احملــدد حضــر املذكــور ومعــه املــرأة ‪...... /‬اثيوبيــة اجلنســية يف ســيارة‬\n      ‫أجــرة نــزل واســتلم املبلــغ املرقــم مــن املصــدر ثــم رجــع لســيارة األجــرة‬\n      ‫وأخــذ الكيــس كمــا نزلــت املــرأة ومعهــا كيــس ومشــيا داخــل مــكان‬\n      ‫بــه عــدد مــن الســيارات املتوقفــة وقــام باإلشــارة للمصــدر لطلــب حضــوره‬\n      ‫وقامــا بتســليم املصــدر الكيســن ومت اســتيقافهما وتبــن بــأن بــكل‬\n      ‫كيــس عــدد ســت قواريــر ســعة لتــر ونصــف مليئــة باخلمــور املصنعــة‬\n      ‫محليــا (العــرق ) كمــا ضبــط املبلــغ املرقــم معــه وذكــرت املــرأة ان‬\n      ‫لديهــم مصنــع للخمــور يعمــان بــه منــذ شــهرين جــرى تســليم احملضــر‬\n      ‫والرجــل ملركــز شــرطة ‪......‬وإيــداع املــرأة ســجن النســاء مــن قبــل اجلهــة‬\n                                                               ‫القابضــة رهــن التحقيــق‬\n      ‫جــرى اســتجواب األول ‪...... /‬قــدم للبــاد عــن طريــق التهريــب وقــد اصــر‬\n                                                                            ‫علــى أقوالــه ‪.‬‬\n      ‫جــرى اســتجواب الثانــي ‪...... /‬ذكــر بأنهــا تعمــل يف املصنــع منــذ اســبوع‬\n      ‫مــع االول ‪...... /‬وإنهــا تعمــل معــه وهــي تتقاضــى رابــت شــهري قــدره ثالثة‬\n                ‫آالف رســال وذكــرت بأنهــا قدمــت للبــاد عــن طريــق التهريــب ‪.‬‬\n      ‫جــرى املكاتبــة إلدارة االدلــة اجلنائيــة بالكتــاب رقــم (‪ )......‬وتاريــخ‬\n      ‫‪1433/7/19‬ه ـ لتحليــل املــادة املضبوطــة بحوزتــه ووردنــا كتابهــم‬\n      ‫رقــم (‪ )......‬يف ‪1433/8/20‬ه ـ املرفــق بــه ‪ ......‬تقريــر رقــم ‪......‬املتضمــن‬\n      ‫إيجابيــة العينــة وان املــادة حتتــوي نســبة ‪ %43‬مــن الكحــول االيثيلــي‬\n\n\n‫‪309‬‬\n\f‫جــرى فــرز اوراق مســتقلة وإحالتهــا إلدارة الوافديــن مبوجــب كتابنــا‬\n‫رقــم ‪......‬وتاريــخ ‪1433/7/27‬ه ـ ملعاجلــة إقامــة املتهمــن يف البــاد‬\n                                                      ‫بطريقــة غيــر مشــروعة ‪.‬‬\n‫وقــد انتهــى التحقيــق الــى توجيــه االتهــام للمذكوريــن بتصنيــع وترويــج‬\n      ‫اخلمــور املصنعــة محليــا (العــرق ) وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n                             ‫‪ -1‬ما ورد يف محضر القبض املرفق لفه رقم ( )‬\n‫‪ -2‬اعتــراف املتهمــة بتصنيــع اخلمــور باالشــتراك مــع املتهــم وتتقاضــى‬\n‫مقابــل ذلــك مبلــغ ثالثــة االف ريــال كراتــب شــهري منــه والــذي يقــوم‬\n‫هــو بــدوره بترويــج تلــك اخلمــور بكــد اكتمــال عمليــة التصنيــع املــدون‬\n                                ‫مبلــف التحقيــق لفــه رقــم ‪11‬صفحــة رقــم ( )‬\n‫‪ -3‬التقريــر املخبــري املتضمــن ايجابيــة العينــة املعثــور عليهــا بحوزتــه وان‬\n     ‫املــادة حتتــوي نســبة ‪ %41‬مــن الكحــول االيثيلــي املرفــق لفــه رقــم ( )‬\n‫وحيــث أن مــا اقــدم عليــه املذكــور فعــل محــرم شــرعا ومعاقــب عليــه‬\n‫نظامــا لــذا اطلــب اثبــات مــا اســند اليهمــا واحلكــم عليهمــا بعقوبــة‬\n                                                             ‫تعزيريــه لقــاء ذلــك ‪.‬‬\n‫وبــاهلل التوفيــق وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪_......‬‬\n‫اثيوبــي اجلنســية مبوجــب اثبــات هويــة مؤقــت اجــاب حــال كونــه يتكلــم‬\n‫العربيــة بطالقــة بقولــه مــا جــاء يف دعــوى املدعــي العــام مــن قيامــي‬\n‫بتصنيــع اخلمــر فصحيــح فانــا اعمــل يف مصنــع خمــور وهــو ال يعــود لــي‬\n‫وامنــا يعــود لشــخص ال اعرفــه وقــد عــرض علــي احــد اصدقائــي يدعــى‬\n‫‪......‬بالعمــل فيــه فقمــت بالعمــل فيــه ومــا جــاء يف دعــوى املدعــي العــام‬\n‫مــن قيامــي بترويــج وبيــع اخلمــور فهــذا غيــر صحيــح فانــا لــم يســبق ان‬\n‫قمــت ببيــع اخلمــور مطلقــا هكــذا اجــاب‪ .‬وبعــرض ذلــك علــى املدعــي‬\n\n\n                                                                                        ‫‪310‬‬\n\f      ‫العــام اجــاب بقولــه اطلــب الرجــوع للمعاملــة لالطــاع علــى مــا جــاء فيهــا‬\n      ‫مــن ادلــة وقرائن‪.‬ورفعــت اجللســة الــى يــوم غــد االثنــن ‪1434/3/23‬ه ـ‬\n      ‫‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬ويف يــوم االثنــن‬\n      ‫‪1434/3/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n      ‫حلضــوره املدعــى عليــه وقــد جــرى طلــب الســجينة ‪......‬ولــم يتــم‬\n      ‫احضارهــا مــن ســجن النســاء وبالرجــوع للمعاملــة وجــد فيهــا محضــر‬\n      ‫القبــض الصــادر مــن مركــز هيئــة االمــر باملعــروف والنهــي عــن املنكــر‬\n      ‫بحــي ‪......‬برقــم ‪......‬يف ‪1433/7/19‬ه ـ ونــص احلاجــة منه‪:‬لقــد توفــرت‬\n      ‫معلومــات عــن االول ‪......‬بترويــج اخلمــور املصنعــة محليــا فتــم االتفــاق‬\n      ‫معــه هــذا اليــوم عــن طريــق احــد املصــادر علــى شــراء كرتــون خمــر‬\n      ‫اثنــا عشــر قــاروره ســعة لتــر ونصــف مببلــغ خمســمائة ريــال ويف املــكان‬\n      ‫احملــدد حضــر االول ومعــه الثانيــة يف ســيارة اجــره ونــزل االول واســتلم‬\n      ‫املبلــغ املرقــم مــن املصــدر امامنــا وقــدره خمســمائة ريــال ثــم رجــع الــى‬\n      ‫الســيارة االجــرة واخــذ كيــس كمــا نزلــت الثانيــة ومعهــا كيــس‬\n      ‫ومشــيا داخــل مــكان بــه مجموعــة مــن الســيارات املتوقفــة وقــام االول‬\n      ‫باإلشــارة للمصــدرة لطلــب حضــوره وقــام بتســليم املصــدر الكيســن‬\n      ‫فتــم اســتيقافهما وتبــن ان بــكل كيــس ســت قواريــر ســعة لتــر ونصــف‬\n      ‫مليئــة باخلمــر املصنــع محليــا كمــا ضبــط املبلــغ املرقــم مــع االول وذكــر‬\n      ‫االول والثانيــة ان لديهــم مصنــع للخمــور وانهمــا يعمــان هــذا العمــل منــذ‬\n      ‫شــهرين‪.‬أ ه ـ ‪ .‬واحملضــر موقــع عليــه مــن قبــل ثالثــة اعضــاء وبعــرض‬\n      ‫احملضــر علــى املدعــى عليــه اجــاب بقولــه ال صحــة ملــا جــاء يف احملضــر‬\n      ‫فانــا لــم اقــم ببيــع اي خمــور والصحيــح مــا جــاء يف جوابــي علــى الدعــوى‬\n      ‫وبالرجــوع للمعاملــة وجــد فيهــا دفتــر التحقيــق لفــة رقــم‪ 1‬صــ‪ 3‬اعتــراف‬\n\n\n‫‪311‬‬\n\f‫املدعــى عليهــا ‪......‬بانهــا تعمــل خادمــة عنــد املدعــى عليــه ‪......‬يف مصنــع‬\n‫اخلمــور وأنهــا تســتلم منــه راتبــا وقــدره ثالثــة االف ريــال‪ .‬أ ه ـ ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف اقوالهــا‬\n‫والصحيــح مــا جــاء يف جوابــي علــى الدعــوى هكــذا أجــاب ‪ .‬وبالرجــوع‬\n‫للمعاملــة وجــد فيهــا التقريــر الكيميائــي رقــم ‪1433/575‬ه ـ واملتضمن‬\n‫إيجابيــة املــادة الســائلة للحكــول االثيلــي بنســبة ‪ .%43‬أ ه ـ ‪ .‬فبنــاء علــى‬\n‫مــا تقــدم وحيــث صــادق املدعــى عليــه علــى قيامــه بتصنيــع اخلمــور‬\n‫وانكــر مــا جــاء يف دعــوى املدعــي العــام مــن ترويجهــا وحيــث أن مــا‬\n‫جــاء يف محضــر القبــض وأقــوال املدعــى عليهــا ‪......‬لــدى جهــات التحقيــق‬\n‫تــورث الشــبهة القويــة جتاهــه حيــال الترويــج والتعزيــر يجــب بالشــبهة‬\n‫فعليــه فقــد ثبــت لــدي قيــام املدعــى عليــه بتصنيــع اخلمــور وتوجــه الشــبهة‬\n‫القويــة جتاهــه بترويــج اخلمــور وقــرر تعزيــره لقــاء ذلــك بســجنه ســنة مــن‬\n‫تاريــخ إيفاقــه وجلــده مائــة وخمســن جلــده مفرقــة علــى ثــاث دفعــات‬\n‫كل دفعــة خمســون جلــده بــن كل دفعــة وأخــرى عشــرة أيــام وبذلــك‬\n‫حكمــت‪ .‬وأوصــي بإبعــاد املدعــى عليــه لبــاده بعــد انتهــاء محكوميتــه‬\n‫وعــدم دخــول هــذه البــاد مطلقــا ‪.‬وبعــرض احلكــم علــى املدعــي العــام‬\n‫قــرر االعتــراض مكتفيــا بالئحــة الدعــوى أمــا املدعــى عليــه فقــد قــرر‬\n‫القناعــة باحلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض و يف يــوم الثالثــاء املوافــق‪ 1434/03/24‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 12،00‬وفيهــا حضــر املدعــي العــام وحضــرت حلضــوره املدعــى‬\n‫عليهــا ‪......‬أثيوبيــة اجلنســية مبوجــب بطاقة نزيلة ســجون برقم ‪33/5/28‬‬\n‫وبعــرض دعــوى املدعــي العــام عليهــا أجابــت حــال كونهــا تتكلــم اللغــة‬\n\n\n                                                                                      ‫‪312‬‬\n\f      ‫العربيــة بقولهــا مــا جــاء يف دعــوى املدعــي العــام كلــه غيــر صحيــح‬\n      ‫فأنــا ال أقــوم ببيــع اخلمــور وكــذا ال أقــوم بتصنيعهــا وإمنــا أنــا أعمــل‬\n      ‫يف مصنــع خمــور كعاملــة نظافــة فقــط وال عالقــة لــي بتصنيــع اخلمــور‬\n      ‫وكــذا لــم يســبق لــي أن قمــت ببيــع اخلمــور مطلقــا هكــذا أجابــت‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه أكتفــي مبــا جــاء يف‬\n      ‫اجللســة املاضيــة مــن أدلــة وقرائــن تديــن املدعــى عليهــا هكــذا أجــاب ثــم‬\n      ‫جــرى عــرض إقرارهــا املــدون يف اجللســة املاضيــة فأجابــت نعــم أنا أســتلم‬\n      ‫راتــب مــن املدعــى عليــه ‪......‬هكــذا أجابــت فبنــاء علــى مــا تقــدم وحيــث‬\n      ‫صادقــت املدعــى عليهــا علــى قيامهــا بالعمــل يف مصنــع اخلمــور يف مجــال‬\n      ‫النظافــة وأنكــرت قيامهــا بالتصنيــع والترويــج وحيــث أن مــا جــاء يف‬\n      ‫محضــر القبــض يــورث الشــبهة القويــة جتاههــا فعليــه فقــد ثبــت لــدي‬\n      ‫قيــام املدعــى عليهــا بالعمــل يف مصنــع خمــور يف مجــال النظافــة وتوجــه‬\n      ‫الشــبهة القويــة جتاههــا بترويــج وتصنيــع اخلمــور وقــررت تعزيرهــا وذلــك‬\n      ‫بســجنها تســعة أشــهر مــن تاريــخ إيقافهــا وجلدهــا خمســن جلــدة دفعــة‬\n      ‫واحــدة وبذلــك حكمــت وبعرضــه علــى املدعــي العــام قــرر االعتــراض‬\n      ‫مكتفيــا بالئحــة الدعــوى أمــا املدعــى عليهــا فقــد قــررت القناعة وباهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف ‪ 1434/03/24‬ه ـ احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن‬\n      ‫قضــاة الدائــرة الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن رئيــس احملكمــة اجلزائيــة بالريــاض‬\n      ‫برقــم ‪ 331779513‬وتاريــخ ‪1434/5/29‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمة الشــيخ‪...... /‬املســجل برقــم ‪34202301‬‬\n      ‫وتاريــخ ‪1434/4/30‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد كل مــن‬\n\n\n‫‪313‬‬\n\f‫‪ (...... /2...... /1‬اثيوبيــان اجلنســية ) يف قضيــة مخــدرات علــى النحــو‬\n‫املوضــح بالصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه ‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة‬\n‫مــا يوجــب املالحظــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                               ‫محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                ‫احملكمة اجلزائية بالرياض‬\n                           ‫ضبط القضايا اجلنائية ‪ /‬املكتب القضائي ‪37‬‬\n                       ‫صحيفة رقم ‪ 90‬مجلد الضبط رقم ‪/37/36‬جنائي‬\n‫اجللســة رقــم (‪ )4‬تابعــة للقضيــة املقيــدة رقــم (‪ )331779513‬املضبوطــة‬\n                                      ‫مبجلــد (‪/37/28‬جنائــي) صفحــة(‪)88‬‬\n‫ويف يــوم االحد‪1434/08/07‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34202301‬وتاريــخ‬\n‫‪1434/04/30‬ه ـ واملتعلــق بدعــوى املدعــي العــام ضــد ‪ ..../‬وقــد تضمــن‬\n‫القــرار املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                                                ‫نبينــا محمــد‪.‬‬\n\n\n\n\n                                                                                  ‫‪314‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":307,"source_page_end":314,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14a6192e5d9386002c8d521611da5ed6d2bead6c54aad4c73bb30468b25d824d","normalized_text_hash":"fc70bd94fb2a7c420e2c3d61712c72c7fd964b25bad08e69eb272ed824cd09b0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p307-34202301"},{"id":"16ac5174-e002-5ed5-b570-cf3bc0a685da","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تصنيع وترويج وتعاطي -شهادة بوجود املصنع يف املنزل -كبر كمية املادة احملظورة -إقامة حد املسكر وتعزير بالسجن واجللد واإلبعاد.","document_number":"34221250","case_number":"34205048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/25","year":"1434","subject":"مسكر -تصنيع وترويج وتعاطي -شهادة بوجود املصنع يف املنزل -كبر كمية املادة احملظورة -إقامة حد املسكر وتعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34221250:‬تاريخه‪1434/05/25 :‬هـ‬\n                           ‫رقم الدعوى‪34205048:‬‬\n                     ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34323126:‬تاريخه‪1434/09/21:‬هـ‬\n\n\n        ‫مســكر ‪ -‬تصنيــع وترويــج وتعاطــي ‪ -‬شــهادة بوجــود املصنــع يف املنــزل‬\n        ‫‪ -‬كبــر كميــة املــادة احملظــورة ‪ -‬إقامــة حــد املســكر وتعزيــر بالســجن‬\n                                                                  ‫واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n                                             ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n        ‫ادعــى املدعــي العــام علــى املدعــى عليهمــا بتصنيعهمــا العــرق املســكر‬\n        ‫وحيازتهمــا لــه بقصــد الترويــج وللمدعــى عليــه الثانــي بشــرب العــرق‬\n        ‫املســكر وطلــب إثبــات مــا أســند إليهمــا وإيقــاع العقوبــة التعزيريــة لهمــا‬\n        ‫وإقامة حد املســكر على الثاني وتشــديد العقوبة عليه لتعدد ســوابقه‪،‬‬\n        ‫حيــث ورد للشــرطة بــاغ عــن قيــام املدعــى عليهمــا بترويــج املســكر‬\n        ‫ومبداهمــة املنــزل ‪ -‬ظهــر بــأن املنــزل يعــود لوالــدة املدعــى عليهمــا وهمــا‬\n        ‫يســكنان فيــه وضبــط املدعــى عليــه الثانــي أمــام بــاب املنــزل ورائحــة‬\n        ‫املســكر تفــوح مــن فمــه وضبــط املدعــى عليــه األول داخــل املنــزل‬\n        ‫فجــرى تفتيــش املنــزل فلــم يعثــر علــى مــا يوجــب التنويــه ‪ -‬جــرى الصعــود‬\n        ‫للملحــق العلــوي فعثــر علــى غرفــة حتــت اإلنشــاء معــدة لتصنيــع اخلمــور‬\n        ‫حيــث عثــر علــى جالــون أبيــض بــه مــادة شــفافة يشــتبه بأنهــا مــن العــرق‬\n\n‫‪315‬‬\n\f‫وســبعة عشــر قــارورة مــاء صحــة بســعة لتــر ونصــف ومجموعــة براميــل‬\n‫وجــرى إتــاف املضبوطــات بحضــور منــدوب هيئــة األمــر باملعــروف ‪-‬‬\n‫ورد تقريــر مركــز الســموم باحتــواء العينــة املرســلة علــى كميــة مــن‬\n‫الكحــول بنســبة ‪ ، %34‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء‬\n‫عينــة دم املدعــى عليــه الثانــي علــى الكحــول كمــا أقــر املدعــى عليــه‬\n‫األول حتقيقــا بأنــه ميلــك املضبوطــات املعــدة لتصنيــع اخلمــر ودفــع بأنهــا‬\n‫لالســتعمال الشــخصي وأنكــر املدعــى عليــه األول أثنــاء احملاكمــة‬\n‫دعــوى املدعــي العــام وقــرر بأنــه ليــس لــه عالقــة باملضبوطــات وال علــم‬\n‫لــه بهــا وأنــه يســكن وزوجتــه وأوالده مــع والدتــه وأن أخــاه املدعــى عليــه‬\n‫الثانــي هــو الــذي يســكن يف امللحــق العلــوي وأنــه ال يصعــد إليــه وال يعلــم‬\n‫مــا بــه وأقــر املدعــى عليــه الثانــي بتعاطيــه املســكر وأن املضبوطــات‬\n‫تعــود لــه ودفــع بأنهــا لالســتعمال الشــخصي ال للترويــج وصــدق أخــاه‬\n‫املدعــى عليــه األول بأنــه ال عالقــة لــه بهــذه املضبوطــات وال علــم لــه‬\n‫بهــا و بطلــب البينــة مــن املدعــي العــام علــى مــا أنكــره املدعــى عليــه‬\n‫األول أحضــر رجــان قــررا بأنهمــا مــن رجــال الشــرطة وأنــه ورد للشــرطة‬\n‫بــاغ عــن قيــام املدعــى عليــه بتصنيــع وترويــج املســكر فلمــا صــدر‬\n‫اإلذن باملداهمــة وجــدا املدعــى عليــه الثانــي أمــام بــاب املنــزل يف حالــة‬\n‫ســكر فلمــا دخــا املنــزل عثــرا يف الغرفــة الواقعــة يف ســطح املنــزل‬\n‫أدوات مخصصــة لتصنيــع اخلمــر مــن جوالــن ومواســير وقواريــر وقــرر‬\n‫بــأن الغرفــة يصعــد لهــا عبــر ســقالة ثــم جــرى تعديــل الشــهود ‪ -‬بعــرض‬\n‫شــهادتهما علــى املدعــى عليــه األول أنكــر علمــه باملصنــع ودفــع بــأن‬\n‫الســقالة كانــت لنقــل األثــاث ‪ ،‬لــذا فقــد حكمــت احملكمــة مبــا يلــي‪:‬‬\n‫بتعزيــر املدعــى عليــه الثانــي بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه‬\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫وجلــده أربعمائــة جلــدة كمــا ثبــت إدانتــه بشــرب املســكر وبجلــده‬\n      ‫ثمانــن جلــدة دفعــة واحــدة وبــن جلــد احلــد وجلــد التعزيــر شــهر ‪،‬‬\n      ‫والتوصيــة بإبعــاده عــن البــاد ومنعــه مــن العــودة لهــا اتقــاء لشــره وكثــرة‬\n      ‫ســوابقه ‪ ،‬وبتعزيــر املدعــى عليــه األول بالســجن ســنتني ابتــداء مــن‬\n      ‫تاريــخ التوقيــف وجلــده مئتــن وخمســن جلــدة بعــرض احلكــم علــى‬\n      ‫املدعــى عليهمــا لــم يقنعــا بــه وطلبــا االســتئناف بــدون الئحــة وال زال‬\n      ‫املدعــي العــام علــى اعتراضــه مكتفيــا مبــا ســبق ‪ -‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34205048‬وتاريــخ‬\n      ‫‪1434/05/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341093073‬وتاريــخ‬\n      ‫‪1434/5/4‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/05/06‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 15‬وفيهــا حضــر املدعــي العــام ‪...........‬مبوجــب‬\n      ‫خطــاب التكليــف مــن مرجعــه ‪...........‬يف ‪1434/5/5‬ه ـ وادعــى علــى‬\n      ‫احلاضرين كل من ‪ ،...........- 1‬البالغ من العمر (‪ )43‬عام ًا ‪ ،‬سعودي‬\n      ‫اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم( ‪ ،...........-2 )...........‬البالــغ‬\n      ‫مــن العمــر (‪ )33‬عام ـ ًا ‪ ،‬مينــي اجلنســية ‪ ،‬مبوجــب البطاقــة البديلــة‬\n      ‫رقــم(‪ )...........‬وتاريــخ ‪1434/4/1‬ه ـ حيــث أنــه بتاريــخ ‪1434/1/29‬ه ـ‬\n      ‫ورد ملركــز شــرطة ‪...........‬خطــاب مديــر شــعبة التحريــات والبحــث‬\n      ‫اجلنائــي املتضمــن توفــر معلومــات عــن قيــام شــخصني ببيــع وترويــج‬\n\n‫‪317‬‬\n\f‫العــرق املســكر يف منطقــة شــارع ‪...........‬حــارة ‪...........‬وجــرى العــرض‬\n‫لصاحــب الســمو امللكــي أميــر منطقــة مكــة املكرمــة لالســتئذان‬\n‫حيــال مداهمــة املنــزل فــوردت برقيــة ســموه رقــم(‪ )...........‬يف‬\n‫‪1434/3/22‬ه ـ باملوافقــة علــى املداهمــة وفــق ضوابــط املداهمــة وعليــه‬\n‫مت رصــد ومتابعــة املوقــع للتأكــد مــن وجــود صاحــب املنــزل ويف متــام‬\n‫الســاعة السادســة صباحـ ًا جــرى مداهمــة املوقــع وأتضــح أنــه عبــارة عــن‬\n‫منــزل شــعبي مكــون مــن دوريــن وملحــق ‪ ،‬عائــد للمــرأة‪،.........../‬‬\n‫ســعودية اجلنســية ويســكن معهــا ابنهــا املدعــى عليــه األول‪.........../‬وهــو‬\n‫الشــخص الــذي تفيــد التحريــات أنــه هــو مــن يقــوم بتصنيــع العــرق‬\n‫املســكر وقــد مت ضبــط املدعــى عليــه الثاني‪.........../‬أثنــاء جلوســه أمــام‬\n‫بــاب املنــزل وأتضــح أنــه تنبعــث منــه رائحــة العــرق املســكر فتــم دخــول‬\n‫املنــزل ومت ضبــط املدعــى عليه‪.........../‬املذكــور بداخلــه وبتفتيشــه‬\n‫املنــزل لــم يعثــر علــى مــا يوجــب التنويــة ثــم جــرى الصعــود للملحــق العلوي‬\n‫الــذي اليــزال حتــت اإلنشــاء وعثــر علــى غرفــة مــن الطــوب األحمــر فــوق‬\n‫الســطح أتضــح أنهــا معــدة لتصنيــع العــرق املســكر حيــث وجــد بداخلهــا‬\n‫جالــون أبيــض بــه النصــف مــن مــادة شــفافة اللــون يحتمــل أن تكــون‬\n‫مــادة العــرق املســكر وجالــون أبيــض بــه النصــف مــن مــادة شــفافة اللــون‬\n‫يحتمــل أن تكــون مــادة العــرق املســكر وعــدد ســبعة عشــر قــارورة‬\n‫صحــة كبيــر (‪)...........‬ســعة لتــر ونصــف اللتــر حتتــوي علــى مادة شــفافة‬\n‫اللــون يشــتبه أن تكــون مــادة العــرق املســكر وعــدد واحــد برميــل مــاء‬\n‫برتقالــي بــه النصــف مــن مــادة ســائلة شــفافة اللــون يحتمــل أن تكــون‬\n‫مــادة العــرق املســكر وعــدد اثنــن برميــل فيبــر جــاس بيضــاء معــدة‬\n‫للتقطيــر وعــدد واحــد برميــل معــد للتقطيــر وعــدد واحــد برميــل أزرق‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫للتخميــر ونصــف برميــل بالســتيك أزرق للتخميــر وجالــون ســعة عشــرون‬\n      ‫لتــر بــه مــادة ســائله شــفافة اللــون ومعهــا قطــع برتقــال مخمــرة وعــدد‬\n      ‫واحــد برميــل معــد للتقطيــر خــارج الغرفــة أزرق اللــون وقــد جــرى إتــاف‬\n      ‫املضبوطــات بحضــور منــدوب هيئــة األمــر باملعــروف والنهــي عــن املنكر‬\n      ‫بشــارع ‪...........‬عــدا قــارورة واحــد مت بعثهــا ملركــز الســموم لفحصهــا‬\n      ‫وقــد ورد تقريــر رقم‪...........‬املتضمــن احتــواء العينــة املرســلة مــن الكمية‬\n      ‫املضبوطــة علــى مــادة الكحــول بنســبة(‪ )%34‬قــد أثبــت التقريــر‬\n      ‫الكيميائــي الطبــي الشــرعي رقــم (‪...........‬وتاريــخ ‪1434/4/1‬ه ـ‬\n      ‫احتــواء عينــة دم املدعــى عليــه الثاني‪.........../‬علــى مــادة الكحــول‬\n      ‫املســكر وباســتجواب املدعــى عليــه‪ ....................../‬أفــاد أن معــدات‬\n      ‫تصنيع العرق املســكر عائده ألخيه املدعى عليه ‪............/‬وباســتجواب‬\n      ‫املدعــى عليه‪.........../‬أفــاد أنــه قــام بشــراء معــدات تصنيــع العــرق‬\n      ‫املســكر مــن الســوق قبــل شــهرين ووضعهــا يف الســطح وهــو يقــوم‬\n      ‫بتصنيــع العــرق املســكر بواســطة البراميــل التــي اشــتراها وذكــر أنــه‬\n      ‫يصنــع العــرق لالســتخدام الشــخصي وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام للمدعــى عليهمــا بتصنيــع العــرق املســكر وحيازتهمــا لــه بقصــد‬\n      ‫الترويــج وللمدعــى عليــه الثاني‪.........../‬بشــرب العــرق املســكر وذلــك‬\n      ‫ألدلــة والقرائــن التاليــة ‪-1‬اعتــراف املدعــى عليــه‪ ………/‬املــدون علــى‬\n      ‫ص(‪)10‬و(‪ )11‬مــن ملــف التحقيــق رقم(‪-2)2‬مــا جــاء مبحضــر القبــض‬\n      ‫املنــوه عنــه واملرفــق لفــة رقــم (‪-3)7-6‬تقريــر الكيميــاء اجلنائيــة املنــوه‬\n      ‫عنــه واملرفــق لفــة رقــم ( ‪-4)15‬التقريــر الطبــي الكيميائــي الشــرعي‬\n      ‫رقــم(‪ )5879‬املنــوه عنــه واملرفــق لفــة رقــم(‪ )41‬وبالبحــث عــن ســوابق‬\n      ‫املدعــى عليه‪.........../‬عثــر لــه علــى ســبع ســوابق األولــى فــض البــكارة‬\n\n\n‫‪319‬‬\n\f‫مــع فعــل فاحشــة الزنــا‪ ،‬والثانيــة دخــول منــزل لغــرض ســيئ مقترنــة مــع‬\n‫ســرقة أمــوال ‪ ،‬والثالثــة ســرقة ‪ ،‬والرابعــة حيــازة واســتعمال مخــدرات‬\n‫‪ ،‬واخلامســة اختــاء محــرم واجتمــاع علــى مفســدة ‪ ،‬والسادســة ترويــج‬\n‫املســكرات ‪ ،‬والســابعة صناعــة املســكرات وترويجهــا مقترنــة بحيــازة‬\n‫مســكر وبالبحــث عــن ســوابق املدعــى عليــه ‪ .........../‬عثــر لــه علــى‬\n‫تســعة ســوابق األولــى شــرب املســكرات ‪ ،‬والثانيــة اعتــداء مقترنــة‬\n‫بســرقة أمــوال والثالثــة عــوده بعــد إبعــاد‪ ،‬والرابعــة شــرب وترويــج‬\n‫املســكرات مقترنــة بحيــازة ســاح بــدون ترخيــص ‪ ،‬واخلامســة‬\n‫والســابعة عــوده بعــد إبعــاد ‪ ،‬والسادســة شــرب املســكرات ‪ ،‬والثامنــة‬\n‫شــرب وحيــازة املســكرات ‪ ،‬والتاســعة يف قضايــا مختلفــة وحيــث إن مــا‬\n‫قــام بــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليهمــا واحلكــم‬\n‫عليهمــا بعقوبــة تعزيريــة رادعــه لهمــا واحلكــم املدعــى عليــه الثانــي بحــد‬\n‫املســكر وتشــديد العقوبــة عليهمــا لتعــدد ســوابقهما التــي لــم تردعهمــا‬\n‫عقوبتهمــا اســتناد ًا لبرقيــة صاحــب الســمو امللكــي نائــب وزيــر الداخلية‬\n‫رقــم ‪ 93958/5/5/1‬وتاريــخ ‪1429/8/23‬ه ـ هــذه دعــواي وبســؤال‬\n‫املدعــى عليهمــا أجــاب األول عمــر بقولــه مــا ذكــره املدعــي العــام غيــر‬\n‫صحيــح وليــس لــي عالقــة باملضبوطــات وال أعلــم عنهــا وإننــي أســكن‬\n‫يف منــزل والدتــي املقســوم ومعــي زوجتــي وأوالدي وإن أخــي ‪...........‬‬\n‫يســكن يف امللحــق العلــوي وال أصعــد إليــه وال أعلــم عــن محتويــات‬\n‫غرفتــه هــذه إجابتــي كمــا أجــاب الثانــي ‪...........‬بقولــه مــا ذكــره‬\n‫املدعــي العــام صحيــح حيــث كان بحوزتــي املضبوطــات لتصنيــع‬\n‫املســكر وشــربه وليــس للترويــج حيــث إننــي أتعاطــى املســكر كثيــرا‬\n\n\n                                                                                     ‫‪320‬‬\n\f      ‫وليــس ألخــي ‪...........‬عالقــة وال علــم مبــا يف غرفتــي هــذه إجابتــي وقــال‬\n      ‫املدعــي العــام الصحيــح مــا ذكــرت وبطلــب البينــة علــى الترويــج وعلــى‬\n      ‫تــورط األول قــال ســأفيدكم يف اجللســة القادمــة لــذا رفعــت اجللســة ويف‬\n      ‫يــوم األحــد املوافــق ‪1434/5/19‬ه ـ افتتحــت اجللســة وحضــر فيهــا‬\n      ‫املدعــى عليهمــا وحضــر للشــهادة وادائهــا كل مــن ‪...........‬ســعودي‬\n      ‫بســجل مدنــي رقــم ‪...........‬و ‪...........‬ســعودي بســجل مدنــي رقــم ‪...........‬‬\n      ‫فشــهد كل واحــد منهمــا بقولــه وردتنــا معلومــات عــن قيــام شــخص‬\n      ‫بتصنيــع وترويــج العــرق املســكر فتــم أخــذ اإلذن الرســمي للمداهمــة‬\n      ‫ووجدنــا املدعــى عليــه الثانــي ‪...........‬أمــام املنــزل ســكرانا وأفــاد بوجــود‬\n      ‫أخيــه ‪...........‬باملنــزل وبدخــول املنــزل وجدنــاه شــعبيا مكونــا مــن أربــع‬\n      ‫غــرف مبنافعهــا وبداخلــه ســلم يــؤدي للســطح حيــث وجدنــا غرفــة مهيــأة‬\n      ‫كمصنــع للخمــر باجلوالــن والتمديــدات واملواســير والقواريــر‬\n      ‫واملضبوطــات املذكــورة وال ميكــن جهــل أحــد مــن أهــل املنــزل بهــا ألن‬\n      ‫الســلم (الــدرج) داخــل املنــزل ويوجــد ســقالة بكــرة وحبــال إلنــزال‬\n      ‫املســكرات مــن الســطح إلــى داخــل املنــزل بــدال مــن حملهــا يف الســلم‬\n      ‫ووجدنــا املدعــى عليــه األول ‪...........‬مــع أهلــه يف الــدور األرضــي هــذه‬\n      ‫شــهادتنا وقــال املدعــى عليــه األول مــا ذكــره الشــهود عــن مصنــع اخلمــر‬\n      ‫فلــم أعلــم عنــه وأمــا الســقالة فكانــت لنقــل األثــاث وال أعــرف الشــهود‬\n      ‫ثــم جــرى تعديــل الشــهود مــن قبــل ‪........... ...........‬ورفعــت اجللســة للتأمــل‬\n      ‫ويف يــوم الســبت ‪1434/05/25‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي‬\n      ‫العــام واملدعــى عليهمــا وقــد جــرى تأمــل القضيــة ووجــدت للمدعــى عليــه‬\n      ‫األول ســبع ســوابق منهــا اثنتــان يف تصنيــع وترويــج املســكرات كمــا‬\n      ‫وجــدت للمدعــى عليــه الثانــي تســع ســوابق منهــا ترويــج وشــرب‬\n\n\n‫‪321‬‬\n\f‫مســكرات فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى إقــرار‬\n‫املدعــى عليــه الثانــي ……… بشــرب املســكر وتصنيعــه ووجــود مصنــع‬\n‫اخلمــر بغرفتــه واملضبوطــات الكثيــرة وال يتصــور أنهــا ملجــرد التعاطــي‬\n‫بــل احلــال يــدل علــى قصــد الترويــج لكثــرة القواريــر والبراميــل وبنــاء‬\n‫علــى شــهادة البينــة العادلــة مــع إنــكار املدعــى عليــه األول ‪...........‬وبنــاء‬\n‫علــى الســوابق الكثيــرة للمدعــى عليهمــا وفيهــا ســوابق مشــابهة لهــذه‬\n‫التهمــة ومــع أن األول ‪...........‬أنكــر الدعــوى إال أن ســوابقه املشــابهة‬\n‫وســكنه يف املنــزل ومــا جــاء يف وصــف الشــهود حلالــة املنــزل تــدل علــى‬\n‫اشــتراك املدعــى عليــه األول يف التصنيــع والترويــج أو تســتره علــى األول‬\n‫وعلــى عملــه فــا يتصــور جهلــه مبا يــدور يف منزله مع كثرة املضبوطات‬\n‫والســقالة ووجــود الســلم داخــل املنــزل حســب إفــادة الشــهود لــذا فقــد‬\n‫حكمــت مبــا يلــي أوال‪ :‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪...........‬‬\n‫بتصنيــع العــرق املســكر وحيازتــه لــه بقصــد الترويــج والتعاطــي‬\n‫وحكمــت بتعزيــره علــى ذلــك وعلــى تعــدد الســوابق بالســجن مــدة‬\n‫ســنتني ابتــداء مــن تاريــخ التوقيــف وجلــده ثالثمائــة جلــدة مفرقــة علــى‬\n‫ســت دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى شــهر‬\n‫كمــا ثبــت لــدي إدانتــه بشــرب العــرق املســكر وحكمــت بجلــده حــد‬\n‫املســكر ثمانــن جلــدة دفعــة واحــدة وبــن جلــد احلــد وجلــد التعزيــر مــدة‬\n‫شــهر كمــا أوصيــت بإبعــاده إلــى خــارج اململكــة ومنعــه مــن العــودة‬\n‫إليهــا اتقــاء لشــره وكثــرة ســوابقه ‪ .‬ثانيــا‪ :‬توجــه الشــبهة القويــة جــدا‬\n‫للمدعــى عليــه األول ‪ ...........‬باالشــتراك مــع الثانــي يف تصنيــع املســكر‬\n‫وحيازتــه للمســكر بقصــد الترويــج وتســتره علــى األول وحكمــت‬\n‫بتعزيــره علــى ذلــك وعلــى تعــدد الســوابق بالســجن مــدة ســنة ونصــف‬\n\n\n                                                                                         ‫‪322‬‬\n\f      ‫ابتــداء مــن تاريــخ التوقيــف وجلــده مائتــي جلــدة مفرقــة علــى أربــع دفعات‬\n      ‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى شــهر وبعــرض احلكم‬\n      ‫علــى املدعــى عليهمــا قنعــا بــه وقــد عــارض املدعــي العــام وطلــب‬\n      ‫االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه ‪ .‬حــرر يف ‪1434/05/25‬ه ـ‬\n      ‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n      ‫‪ 34267110‬وتاريــخ ‪1434/07/12‬ه ـ املتضمــن املوافقــة والتصديــق‬\n      ‫علــى احلكــم قاضــي اســتئناف ‪ ...........‬قاضــي اســتئناف ‪ ...........‬قاضــي‬\n      ‫اســتئناف ‪ ...........‬لــذا جــرى إحلاقــه وإثباتــه وبــاهلل التوفيــق حــرر يف‬\n      ‫‪1434/08/03‬ه ـ احلمــد هلل وحــده وبعــد ثــم عادت املعاملــة من محكمة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34267110‬يف ‪1434/7/12‬ه ـ‬\n      ‫املتضمــن املالحظــة باألكثريــة بــأن مــا حكــم بــه علــى املدعــى عليهــم‬\n      ‫جميعــا مــن ســجن وجلــد قليــل جدا وال يتناســب مع جرميتهمــا ولكونهما‬\n      ‫مــن أربــاب الســوابق وقــد حكــم عليهمــا بأكثــر مــن ذلــك فلــم يرتدعــا‬\n      ‫فالبــد مــن زيــادة العقوبــة ألن األحــكام الضعيفــة ال تــردع واهلل املوفــق‪.‬‬\n      ‫انتهــى‪ .‬واجلــواب عمــا ذكــره أصحــاب الفضيلــة أنــه جــرى منــي إعــادة‬\n      ‫التأمــل والدراســة للقضيــة ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد‬\n      ‫قــررت زيــادة احلكــم بتعزيــر املدعــى عليهمــا بالســجن واجللــد ليكــون‬\n      ‫احلكــم بعــد الزيــادة كمــا يلــي ‪ :‬أوال‪ :‬ســجن املدعــى عليــه الثانــي‬\n      ‫‪ ...........‬مــدة ثــاث ســنوات ابتــداء مــن تاريــخ التوقيــف وجلــده أربعمائــة‬\n      ‫جلــدة مفرقــة علــى ثمــان دفعــات كل دفعــة خمســون جلــدة بــن كل‬\n      ‫دفعــة وأخــرى شــهر باإلضافــة إلــى حــد املســكر ثمانــن جلــدة دفعــة‬\n      ‫واحــدة مــع الوصيــة بإبعــاده ‪ .‬ثانيــا‪ :‬ســجن املدعــى عليــه األول ‪...........‬‬\n\n\n‫‪323‬‬\n\f‫مــدة ســنتني ابتــداء مــن تاريــخ التوقيــف وجلــده مائتــن وخمســن جلــدة‬\n‫مفرقــة علــى خمــس دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n‫وأخــرى شــهر وبعــرض احلكــم علــى املدعــى عليهمــا لــم يقنعــا بــه وطلبــا‬\n‫االســتئناف بــدون الئحــة فأجيبــا لطلبهمــا وال زال املدعــي العــام علــى‬\n‫اعتراضــه مكتفيــا مبــا ســبق وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وآلــه وصحبــه ‪ .‬حــرر يف ‪1434/7/26‬ه ـ احلمــد هلل وحــده‬\n‫وبعــد فلــدي أنــا ‪...........‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫القائــم بعمــل املكتــب القضائــي الســادس بنــاء علــى خطــاب التكليــف‬\n‫الصــادر مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة رقــم‬\n‫‪ 342053882‬يف ‪1434/8/24‬ه ـ وعليــه فقــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34323126‬يف‬\n‫‪1434/9/21‬ه ـ املتضمــن املوافقــة والتصديــق علــى احلكــم وبــاهلل‬\n‫التوفيــق ‪ .‬قاضــي اســتئناف‪ .........../‬ختــم‪ .‬توقيــع ‪ .‬قاضــي‬\n‫اســتئناف‪.........../‬ختم‪ .‬توقيــع‪ .‬رئيــس الدائرة‪.........../‬ختــم‪ .‬توقيــع لــذا‬\n‫جــرى إحلاقــه واثباتــه حــرر يف ‪1434/10/18‬هـ احلمد هلل وحده والصالة‬\n                                         ‫والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫رقــم(‪ )341093073‬وتاريخ(‪1434/9/15‬هــ) املرفــق بهــا القــرار‬\n‫رقم(‪)34221250‬وتاريخ(‪1434/5/25‬هـ)الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪...........‬القاضــي يف احملكمــة اجلزائيــة مبكــة املكرمــة ‪،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪........... /‬ســعودي اجلنســية ورفيقــه واملتهمــن‬\n\n\n                                                                                    ‫‪324‬‬\n\f      ‫يف تصنيــع العــرق املســكر‪،‬احملكوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":315,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"658712b24e990f9201b56c1d845237e4b131c1258ef4aa7a53515902b73309b4","normalized_text_hash":"e5969ecb3cf84049c37c10d25c513046cf0923219fb9f174df995fd8368178a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p315-34221250"},{"id":"6ea0c8cc-9632-5538-a57f-0c9cea7b0a85","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تصنيع بقصد التعاطي وبالشرب قبل اإلسام -تعزير بالسجن واجللد واإلبعاد -قلة الكمية املضبوطة -إبعاد .","document_number":"34286877","case_number":"34293921","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/02","year":"1434","subject":"مسكر -تصنيع بقصد التعاطي وبالشرب قبل اإلسام -تعزير بالسجن واجللد واإلبعاد -قلة الكمية املضبوطة -إبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34286877:‬تاريخه‪1434/08/02 :‬هـ‬\n                     ‫رقم الدعوى‪34293921:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34352965:‬تاريخه‪1434/011/06:‬هـ‬\n\n\n ‫مســكر ‪ -‬تصنيــع بقصــد التعاطــي وبالشــرب قبــل اإلســام ‪ -‬تعزيــر‬\n       ‫بالســجن واجللــد واإلبعــاد ‪ -‬قلــة الكميــة املضبوطــة ‪ -‬إبعــاد ‪.‬‬\n\n\n\n\n ‫‪ -1‬قول اهلل تعالى‪« :‬يا أيها الذين آمنوا إمنا اخلمر وامليســر واألنصاب‬\n                 ‫واألزالم رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون»‪.‬‬\n ‫‪ -2‬عــن عمــرو بــن العــاص ‪-‬رضــي اهلل عنــه‪ -‬قــال‪« :‬ملــا جعــل اهلل اإلســام‬\n ‫يف قلبــي أتيــت النبــي صلــى اهلل عليــه وســلم فقلــت ‪ :‬ابســط ميينــك‬\n ‫فألبايعــك ‪ .‬فبســط ميينــه ‪ .‬قــال فقبضــت يــدي ‪ .‬قــال‪ :‬مالــك يــا‬\n ‫عمــرو ؟ ‪ .‬قــال قلــت ‪ :‬أردت أن أشــترط ‪ .‬قــال‪ :‬تشــترط مبــاذا ؟ ‪ .‬قلــت‬\n ‫‪ :‬أن يغفــر لــي ‪ .‬قــال ‪ :‬أمــا علمــت أن اإلســام يهــدم مــا كان قبلــه ؟‬\n ‫وأن الهجــرة تهــدم مــا كان قبلهــا ؟ وأن احلــج يهــدم مــا كان قبلــه‬\n                                                                                              ‫؟»أخرجــه مســلم‪.‬‬\n ‫‪ -3‬حديــث ابــن عمــر ‪-‬رضــي اهلل عنهمــا‪ -‬قــال‪ :‬قــال رســول اهلل صلــى اهلل‬\n       ‫عليــه وســلم‪« :‬لعــن اهلل اخلمــر َ َو َشــا ِر َب َها َو َســاقِ َي َها َو َبائ َِع َهــا َو ُمب َت َ‬\n ‫اع َهــا‬\n ‫امل ُمو َل ـ َة ِإ َلي ـ ِه ) أخرجــه أبــوداود‬             ‫اص َر َهــا َو ُمع َت ِص َر َهــا َو َحامِ َل َهــا َو َ‬\n                                                                                                                   ‫َو َع ِ‬\n                                                                                          ‫وصححــه األلبانــي‪.‬‬\n\n\n\n\n                                                                                                                             ‫‪326‬‬\n\f      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتصنيــع قارورتــن مــن اخلمــر‬\n      ‫املســكر يف غرفتــه بقصــد الشــرب وتعاطيــه املســكر وطلــب إثبــات‬\n      ‫مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة عليــه حيــث وردت إخباريــة‬\n      ‫مــن كفيلــه بحيازتــه ملــادة تنبعــث منهــا رائحــة املســكر يف غرفتــه‪،‬‬\n      ‫أقــر املدعــى عليــه بقيامــه بتصنيــع املســكر بقصــد الشــرب وأنــه قــام‬\n      ‫بســكبها ولــم يشــرب منهــا شــيئا وأنــه شــربها يف بلــده قبــل أن يدخــل‬\n      ‫يف ديــن اإلســام وبطلــب البينــة مــن املدعــي العــام قــرر بأنــه ال بينــة لديــه‬\n      ‫ـاء علــى مــا تقــدم حكمــت‬       ‫ســوى مــا هــو مرفــق بــأوراق املعاملــة ‪ ،‬بنـ ً‬\n      ‫احملكمــة بجلــده خمــس وســبعني جلــدة دفعــة واحــدة وســجنه أربعــة‬\n      ‫أشــهر‪ ،‬وثبــت لــدى احملكمــة إدانــة املدعــى عليــه بشــرب املســكر قبــل‬\n      ‫دخولــه اإلســام وقــررت عــدم تعزيــره لقــاء ذلــك ملــا ذكــر ومبــا تقــدم‬\n      ‫حكمــت كمــا رأت إبعــاده عــن البــاد وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة بينمــا املدعــي العــام االعتــراض بالئحــة‬\n                                          ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬       ‫ُ‬\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n      ‫بالدمــام ويف يــوم االثنــن املوافق‪1434/08/01‬ه ـ افتتحت اجللســة وفيها‬\n      ‫ا فيهــا‬\n             ‫قــدم املدعــي العــام ‪...........‬دعــواه ضــد املدعــى عليــه ‪...........‬قائ ـ ً‬\n      ‫حيــث إنــه باالطــاع علــى أوراق القضيــة تبــن أنــه بتاريــخ ‪1434/6/6‬ه ـ‬\n      ‫تقــدم أحــد املواطنــن ملركــز شــرطة شــمال الدمــام ببــاغ مفــاده قيــام‬\n\n‫‪327‬‬\n\f‫ســائقه املدعــو ‪........... /‬املدعــى عليــه ) بحيــازة قــارورة خمــر فارغــة‬\n‫تنبعــث منهــا رائحــة كريهــة يف غرفتــه وأضــاف أن املذكــور هــو زوج‬\n‫العاملــة املنزليــة ( ‪ )...........‬و التــي اتهمهــا يف قضيــة ســرقة ( مت حفــظ‬\n‫االتهــام يف قضيــة الســرقة ) وباستشــمام قــارورة املــاء الفارغــة ( مــاء‬\n‫‪ )...........‬التــي أحضرهــا املدعــي وأفــاد أنــه عثــر عليهــا يف غرفــة املدعــى‬\n‫عليــه تبــن أنــه ينبعــث منهــا رائحــة كريهــة تشــبه رائحــة املســكر ‪.‬‬\n‫وبســماع أقــوال املدعــى عليــه أفــاد انــه قبــض عليــه بســب بــاغ كفيلــه‬\n‫عنــه حيــث عثــر كفيلــه علــى قارورتــن خمــر مســكر صغيــرة قــام‬\n‫بإعدادهــا بقصــد االســتعمال الشــخصي وأقــر بأنــه يشــرب املســكر‬\n‫فقــط وأنــه قــام بإتــاف املســكر يف احلمــام وباســتجوابه أقــر بأنــه‬\n‫اشــترى قواريــر مــاء كبيــرة و وضــع فيهــا ســكر و خميــرة لكــي يصنــع‬\n‫املســكر و بعــد ســبعة أيــام مــن تصنيعــه ســكبه يف احلمــام وأضــاف أن‬\n‫قصــده مــن ذلــك هــو التعاطــي وقــد انتهــى التحقيــق إلــى اتهــام املدعــى‬\n‫عليــه بتصنيــع قارورتــن خمــر مســكر يف غرفتــه لقصــد الشــرب و‬\n‫تعاطــي املســكر وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه املــدون‬\n‫علــى ص رقــم (‪ )5‬مــن امللــف املرفــق علــى اللفــة رقــم ( ‪ ) 2‬و علــى اللفــة‬\n‫رقــم ‪ -2 8‬محضــر االثبــات املــدون علــى ص رقــم (‪ )4‬مــن امللــف املرفــق‬\n‫علــى اللفــة رقــم (‪ )2‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرعا فعــل محــرم و معاقــب عليــه شــرعا أطلــب اثبــات‬\n‫ادانتــه مبــا اســند اليــه و احلكــم عليــه بعقوبــة تعزيريــة تزجــره و تــردع‬\n‫غيــره ويف هــذه اجللســة حضــر املدعــى عليــه ‪...........‬ســيرالنكي اجلنســية‬\n‫مبوجــب رخصــة إقامــة صــادرة مــن الظهــران املــدون بهــا الرقــم ‪...........‬‬\n‫وبعــرض دعــوى املدعــي العــام عليــه بواســطة مترجــم احملكمــة ‪...........‬‬\n\n\n                                                                                       ‫‪328‬‬\n\f      ‫أجــاب قائــا‪ :‬مــا ذكــره املدعــي العــام يف دعــواه صحيــح فقــد قمــت‬\n      ‫بتصنيــع قارورتــن كبيرتــن مــن املســكر كل واحــدة حجمهــا لتــر‬\n      ‫ونصــف بقصــد الشــرب وقمــت بســكبها يف دورة امليــاه ولــم أشــرب منهــا‬\n      ‫وقــد شــربت املســكر يف ســيرالنكا علمـ ًا أننــي دخلــت يف ديــن اإلســام‬\n      ‫قبــل حوالــي ثــاث ســنوات وكان شــربي للمســكر قبــل دخولــي يف‬\n      ‫اإلســام هــذه إجابتــي وبســؤال املدعــى عليــه هــل لديــه بينــة علــى دعــوى‬\n      ‫شــرب املســكر فقــال ليــس لــدي مزيــد بينــة ســوى مــا ورد يف الئحــة‬\n      ‫الدعــوى وأوراق املعاملــة فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام وأقــر بتصنيــع قارورتــي‬\n      ‫املســكر املذكورتــن يف جوابــه عــن الدعــوى بقصــد الشــرب وبشــربه‬\n      ‫للمســكر وحيــث قــرر املدعــى عليــه دخولــه يف اإلســام قبــل ثــاث‬\n      ‫ســنوات وأنــه شــربه للمســكر كان قبــل دخولــه يف اإلســام وحيــث‬\n      ‫أن اإلســام يجــب مــا قبلــه ال ســيما يف احلقــوق اخلاصــة هلل تعالــى وبعــد‬\n      ‫االطــاع علــى طيــات املعاملــة وحيــث جــاء الشــارع احلكيــم بوجــوب‬\n      ‫حفــظ العقــول واألنفــس وصيانتهــا بــل جعــل ذلــك من الضــرورات اخلمس‬\n      ‫ـاب‬\n       ‫نصـ ُ‬     ‫َيسـ ُـر َوا َأل َ‬                                  ‫آم ُنـ ْ‬\n                                    ‫ـوا إِنَّ َــا ا َخلمـ ُـر َوامل ِ‬       ‫ولقولــه تعالــى ( يــا َأ ُّي َهــا الَّذِ يـ َـن َ‬\n      ‫ـون )‬   ‫َّكـ ْـم ُتفل ُِحـ َ‬    ‫ـوه ل ََعل ُ‬\n                                                ‫ـيطانِ َفاج َتن ُِبـ ُ‬      ‫الشـ َ‬‫َوا َأل ْزال َُم ِر ٌجــس ِّمــنْ َع َمـ ِـل َّ‬\n      ‫‪ -‬املائــدة آيــة رقــم ‪ - 90‬وملــا روى أبــو داود وابــن ماجــه عــن ابـ ِـن ُع َمـ َـر‬\n                                ‫الل َص َّلــى َّ ُ‬\n      ‫الل َع َلي ـ ِه َو َس ـل ََّم‬                  ‫‪ -‬رضــي اهلل عنهمــا ‪ -‬قــال ‪ :‬قَ ــالَ َر ُســولُ َّ ِ‬\n      ‫اص َر َهــا‬  ‫اع َهــا َو َع ِ‬                                                                                   ‫‪ ( :‬ل ََعـ َـن َّ ُ‬\n                                     ‫الل ا َخلم َــر َو َشــا ِر َب َها َو َســاقِ َي َها َو َبائ َِع َهــا َو ُمب َت َ‬\n      ‫امل ُمو َل ـ َة ِإ َلي ـ ِه ) ‪ -‬صححــه األلبانــي يف صحيــح‬                              ‫َو ُمع َت ِص َر َهــا َو َحامِ َل َهــا َو َ‬\n      ‫أبــي داود ‪ -‬لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوالً‪ -‬ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بتصنيــع قارورتــي مــن املســكر املذكورتــن يف جوابــه‬\n\n\n‫‪329‬‬\n\f‫عــن الدعــوى بقصــد الشــرب وقــررت معاقبتــه علــى ذلــك بالســجن ملــدة‬\n‫أربعــة أشــهر وجلــده خمــس وســبعني جلــدة دفـ ًة واحــده ‪ .‬ثانيـاً‪ -‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه بشــرب املســكر قبــل دخولــه يف اإلســام وقــررت‬\n‫عــدم تعزيــره لقــاء ذلــك ملــا ُذكــر مــن ضمــن احليثيــات أعــاه وبذلــك‬\n‫أجمــع حكمــت كمــا أرى إبعــاد املدعــى عليــه عــن البــاد بعــد إنفــاذ مــا‬\n‫تقــرر شــرع ًا واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليــه بواســطة املترجــم آنــف الذكــر القناعــة‬\n‫وقــرر املدعــي العــام االعتــراض وطلــب رفع احلكم حملكمة االســتئناف‬\n‫بالئحـ ٍة اعتراضيــة مقدمـ ًة منــه ف ُأجيــب لطلبــه وجــرى إفهامــه أن عليــه‬\n‫احلضــور يــوم الثالثــاء ‪1434/08/02‬ه ـ الســتالم صــورة مــن احلكم وأنه‬\n‫يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار ملــف الدعــوى وســوف‬\n‫يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا يقــدم خاللهــا الئحتــه‬\n‫االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة ســوف يســقط حقــه‬\n‫ويرفــع احلكــم حملكمــة االســتئناف بدونهــا فامتثــل واهلل‬          ‫يف تقدميهــا ُ‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬احلمــد هلل‬\n‫وحــده وبعــد ويف يــوم االثنــن املوافق‪1434/09/07‬ه ـ افتتحــت اجللســة‬\n‫وقــد انتهــت مــدة االعتــراض املنصــوص عليهــا يف املــادة رقــم ( ‪ ) 194‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة ولــم يســتلم املدعــي العــام صــورة احلكــم ولــم‬\n‫يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط حقــه يف تقدميهــا وســوف‬\n‫ـاء علــى املــادة رقــم ( ‪ ) 195‬مــن‬ ‫ُيرفــع احلكــم حملكمــة االســتئناف بنـ ً‬\n‫نظــام اإلجــراءات اجلزائيــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                            ‫وآلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافق‪1434/12/16‬ه ـ فتحــت‬\n\n\n                                                                                       ‫‪330‬‬\n\f      ‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫موجــب اخلطــاب رقــم ‪ 342246665‬يف ‪1434/11/12‬ه ـ وبرفقهــا قــرار‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى مبحكمة االســتئناف‬\n      ‫باملنطقــة الشــرقية رقــم ‪ 34352965‬يف ‪1434/11/06‬ه ـ املتضمــن‬\n      ‫املصادقــة علــى احلكــم لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى‬\n                                                        ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n‫‪331‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":326,"source_page_end":331,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12c1df094e105b55ac25b5fea36cf427970fc3b7782bce174c53fc0e0a69e6ae","normalized_text_hash":"1007afd8f0eb8961eb1961bbd1d5ded924d73ce941c3624501aef12acbfdb9a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p326-34286877"},{"id":"0d49d1ca-4c95-5d7b-a8e8-eadf85b73f7c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تصنيع املسكر -إقرار -تعزير بالسجن واجللد -وإقامة حد املسكر أخذ التعهد -إدانة غير املسلم بالشرب وتعزيره باجللد -ال يقام حد املسكر على الذمي أو املستأمن -قلة الكمية املصنعة ظرف مخفف -تعزير بالسجن واجللد .","document_number":"34266037","case_number":"34319070","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/11","year":"1434","subject":"مسكر -تصنيع املسكر -إقرار -تعزير بالسجن واجللد -وإقامة حد املسكر أخذ التعهد -إدانة غير املسلم بالشرب وتعزيره باجللد -ال يقام حد املسكر على الذمي أو املستأمن -قلة الكمية املصنعة ظرف مخفف -تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34266037:‬تاريخه‪1434/07/11 :‬هـ‬\n                    ‫رقم الدعوى‪34319070:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34274880:‬تاريخه‪1434/07/22:‬هـ‬\n\n\n ‫مســكر‪ -‬تصنيــع املســكر ‪ -‬إقــرار ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬وإقامــة‬\n ‫حــد املســكر أخــذ التعهــد ‪ -‬إدانــة غيــر املســلم بالشــرب وتعزيــره باجللــد‬\n ‫‪ -‬ال يقــام حــد املســكر علــى الذمــي أو املســتأمن‪ -‬قلــة الكميــة املصنعــة‬\n                              ‫ظــرف مخفــف ‪ -‬تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n ‫مــا قــرره جمهــور الفقهــاء مــن احلنفيــة واملالكيــة والشــافعية واحلنابلــة‬\n ‫أنــه ال يقــام احلــد علــى غيــر املســلم‪ ،‬ينظــر املبســوط للسرخســي‬\n ‫(ج‪24‬ص‪ ،)31‬التاج واإلكليل‪( :‬ج‪ 8‬ص ‪ ، )433‬شرح البهجة لألنصاري‪:‬‬\n ‫(ج‪ 5‬ص ‪ )105‬اإلنصــاف للمــرداوي (ج‪ 10‬ص‪ ، )233،232‬قــال البهوتــي‬\n ‫يف كشــاف القناع(ج‪6‬ص‪:« )178‬وال يحد ذمي وال مســتأمن بشــربه أي‬\n                          ‫املســكر ولــو رضــي بحكمنــا ألنــه يعتقــد حلــه» ‪.‬‬\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه األول والثانــي بتصينــع املســكر‬\n ‫بقصــد االســتعمال مــع رفاقهمــا ‪ ،‬وتوجيــه االتهــام للمدعــى عليــه الثالــث‬\n ‫والرابــع بشــرب العــرق املســكر ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n ‫إليهــم واحلكــم علــى األول والثانــي بعقوبة تعزيريــة واحلكم على الثالث‬\n ‫والرابــع بحــد املســكر حيــث تقــدم جارهــم يف مســكنهم ببــاغ ضدهم‬\n ‫بعدمــا ســمع أصواتــا أزعجتــه وبطرقــه الباب خرج أحدهم بحالة ســكر‬\n                                                                                     ‫‪332‬‬\n\f      ‫وبحضــور الفرقــة القابضــة ظهــر وجــود مصنــع خمــر يف منزلهــم وقبــض‬\n      ‫علــى الثالــث والرابــع وهمــا بحالــة غيــر طبيعيــة ‪ -‬أقــر املدعــى عليــه‬\n      ‫األول بتصنيــع املســكر بقصــد الشــرب وقــرر بأنــه نصرانــي الديانــة ‪،‬‬\n      ‫أقــر املدعــى عليــه الثانــي بتصنيــع املســكر بقصــد الشــرب وقــرر بأنــه‬\n      ‫هندوســي الديانــة ‪ ،‬أقــر املدعــى عليــه الثالــث بشــربه املســكر وقــرر‬\n      ‫بأنــه مســلم ‪ -‬أقــر املدعــى عليــه الرابــع بشــربه املســكر وقــرر بأنــه‬\n      ‫هندوســي ‪ -‬جــرى االطــاع علــى محضــر االستشــمام املتضمــن انبعــاث‬\n      ‫رائحــة املســكر مــن املدعــى عليــه الثالــث والرابــع ‪ ،‬بنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى وإلقــرار املدعــى عليهــم ولقلــة الكميــة املصنعــة مــن قبــل‬\n      ‫ـاء‬\n      ‫املدعــى عليــه األول والثانــي وألن املدعــى عليــه الرابــع غيــر مســلم‪ ،‬وبنـ ً‬\n      ‫علــى ذلــك قــررت احملكمــة تعزيــر املدعــى عليــه األول والثانــي بســجن‬\n      ‫كل واحــد منهمــا أربعــة أشــهر ابتــداء مــن توقيــف كل واحــد منهمــا‬\n      ‫بهــذه القضيــة‪ ،‬وجلــد كل واحــد منهمــا مائــة وثمانــن جلــدة مفرقــة‬\n      ‫علــى ثــاث دفعــات ‪ -‬كل دفعــة ســتون جلــدة بــن كل دفعــة وأخــرى‬\n      ‫ســبعة أيــام ‪،‬وأخــذ التعهــد الشــديد علــى كل واحــد منهمــا بعــدم العــودة‬\n      ‫ملثــل هــذه األمــور وتعزيــره‪ ،‬واملدعــى عليــه الرابــع بجلــده خمســن جلــدة‬\n      ‫دفعــة واحــدة علــى مــأ مــن النــاس‪ .‬وأخــذ التعهــد الشــديد عليــه بعــدم‬\n      ‫العــودة ملثــل هــذه األمــور‪ .‬وبجلــد املدعــى عليــه الثالــث ثمانــن جلــدة‬\n      ‫دفعــة واحــدة ‪( -‬حــد املســكر) علــى مــأ النــاس ‪،‬ب‪-‬أخــذ التعهــد‬\n      ‫الشــديد عليــه بعــدم العــودة ملثــل هــذه األمــور‪ ،‬ومبــا تقــدم حكمــت ‪،‬‬\n      ‫كمــا أوصــت بترحيلهــم إلــى بالدهــم بعــد انتهــاء محكوميتهــم بعــد‬\n      ‫أخــذ مــا لهــم ومــا عليهــم مــن حقــوق زجــر ًا لهــم وعبــر ًة لغيرهــم وقــرر‬\n      ‫املدعــى عليهــم القناعــة باحلكــم بينمــا اعتــرض املدعــي العــام وطلــب‬\n       ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬          ‫تدقيــق احلكــم بــا الئحــة ُ‬\n‫‪333‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬رئيــس احملكمــة اجلزائية بحائل‬\n‫وبنــاء علــى املعاملــة احملالــة لنا برقــم ‪ 34319070‬وتاريــخ ‪1434/07/10‬‬\n‫ه ـ واملقيــدة باحملكمــة برقــم ‪ 341650120‬وتاريــخ ‪ 1434/07/09‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافق‪1434/07/11‬ه ـ افتتحــت اجللســة يف متــام‬\n‫الســاعة الثامنــة وفيهــا حضــر املدعــي العــام‪ ،.........../‬وادعــى علــى‬\n‫احلاضريــن معــه‪ -......................-1‬هنــدي اجلنســية ‪-‬مبوجــب رخصــة‬\n‫اإلقامــة رقــم (‪- ...........- 2،)...........‬هنــدي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم (‪ ،........... - 3)...........‬هنــدي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم (‪ -........... -4، )...........‬هنــدي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم (‪ ، )...........‬بالئحــة دعــوى هــذا نصهــا ‪ (:‬فإنــه بتاريــخ‬\n‫‪1434/6/14‬ه ـ املوافــق ليــوم األربعــاء ورد إلــى مركــز شــرطة ‪...........‬‬\n‫بــاغ‪........... /‬املتضمــن أنــه يف الســاعة احلاديــة عشــر مــن مســاء اليــوم‬\n‫املشــار إليــه أعــاه ســمع صــوت إزعــاج مبنــزل املقيمــن املجاوريــن لــه‬\n‫وذهــب لهــم وطــرق بــاب الغرفــة ولــم يفتــح لــه أحــد وصعــد فــوق اجلــدار‬\n‫وخــرج أحدهــم مــن البــاب فقــام باإلمســاك بــه وذهــب إلــى املطبــخ‬\n‫واتضــح لــه بأنهــم يصنعــون اخلمــر ووجــد اثنــان منهمــا عندهمــا قــارورة‬\n‫قامــا بإخفائهــا ‪ ،‬وباالنتقــال إلــى املوقــع مت القبــض علــى الثالــث والرابــع‬\n‫وكانــا بحالــة غيــر طبيعيــة وقبــض علــى األول والثانــي داخــل املطبــخ‬\n‫وبجوارهمــا قــدر بــه مــادة ســائلة يشــتبه أنهــا العــرق املســكر وكذلــك‬\n‫جــر كل بــه العــرق املســكر‪ .‬وباســتجواب األول ‪ /...........‬أقــر أنــه يقــوم‬\n‫بتصنيــع املســكر داخــل ســكنه مــع الثانــي ‪...........‬لغــرض االســتخدام‬\n‫الشــخصي وأنكــر تعاطيــه للمســكر‪ .‬وباســتجواب الثانــي ‪/...........‬‬\n                                                                                      ‫‪334‬‬\n\f      ‫أقــر أنــه يقــوم بتصنيــع املســكر داخــل ســكنه مــع األول ‪...........‬لغــرض‬\n      ‫االســتخدام الشــخصي وأنكــر شــربه للمســكر‪ .‬وباســتجواب الثالــث‬\n      ‫‪ /...........‬أقر بشــرب العرق املســكر مع الرابع‪........... /‬بعد حضورهما‬\n      ‫ملنــزل األول والثانــي وباســتجواب الرابــع ‪ /...........‬أقــر بشــربه املســكر‬\n      ‫مــع الثالــث‪........... /‬عنــد حضورهمــا ملنــزل األول والثانــي‪ .‬وباستشــمام‬\n      ‫أنفاســهم اتضــح انبعــاث رائحــة كريهــة مــن أنفــاس الثالــث‪........... /‬‬\n      ‫والرابــع‪........... /‬تشــبه رائحــة العــرق املســكر‪ .‬وقــد أســفر التحقيــق‬\n      ‫معهــم عــن اتهــام األول والثانــي بتصنيــع املســكر بقصــد االســتعمال مــع‬\n      ‫رفاقهــم ‪ ،‬واتهــام الثالــث والرابــع بشــرب العــرق املســكر وذلــك لألدلــة‬\n      ‫والقرائــن التالية‪-1:‬مــا ورد بإقــرار األول املنــوه عنــه املرفــق لفــة رقــم‬\n      ‫(‪ )1‬ص (‪-2.)7‬مــا ورد بإقــرار الثانــي املنــوه عنــه املرفــق لفــة رقــم (‪)1‬‬\n      ‫ص (‪-3.)9‬مــا ورد بإقــرار الثالــث املنــوه عنــه املرفــق لفــة رقــم (‪ )1‬ص‬\n      ‫(‪-4.)5‬مــا ورد بإقــرار الرابــع املنــوه عنــه املرفــق لفــة رقــم (‪ )1‬ص (‪-5.)4‬‬\n      ‫مــا ورد مبحضــر القبــض املنــوه عنــه املرفــق لفــة رقــم (‪ )2‬ص (‪-6.)6‬مــا‬\n      ‫ورد مبحضــر االستشــمام املنــوه عنــه املرفــق لفــة رقــم (‪ )2‬ص (‪.)13‬‬\n      ‫وباالطــاع علــى ســوابقهم اتضــح عــدم وجــود ســوابق مســجلة عليهــم‪.‬‬\n      ‫وحيــث إن مــا أقدمــوا عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n      ‫إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم علــى األول والثانــي بعقوبــة‬\n      ‫تعزيريــة رادعــة لهمــا وزاجــرة لغيرهمــا واحلكــم علــى الثالــث والرابــع‬\n      ‫بحــد املســكر‪ .‬وبــاهلل التوفيــق ‪ )،،،‬أ‪-‬ه ـ ‪ ،‬هكــذا ادعــى ‪ ،‬وبعــرض‬\n      ‫دعــوى املدعــي العــام علــى املدعــى عليــه األول ‪...........‬عــن طريــق املترجــم‬\n      ‫‪...........‬أجــاب بقولــه ‪:‬صحيــح ‪ ،‬حيــث قمــت بتصنيــع نصــف قــارورة‬\n      ‫صغيــره مــن املســكر (أبــو نصــف ريــال ) ‪ ،‬بقصــد الشــرب ‪ -‬وأنــا‬\n\n\n‫‪335‬‬\n\f‫نصرانــي الديانــة ‪ ،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫الثانــي ‪...........‬عــن طــرق املترجــم ‪...........‬أجــاب بقولــه‪ :‬صحيــح ‪ ،‬حيــث‬\n‫قمــت بتصنيــع نصــف قــارورة صغيــره مــن املســكر (أبــو نصــف ريــال‬\n‫) ‪ ،‬بقصــد الشــرب ‪ ،‬وأنــا هندوســي الديانــة ‪ ،‬وبعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه الثالــث ‪...........‬عــن طــرق املترجــم ‪...........‬أجــاب‬\n‫بقولــه‪ :‬صحيــح ‪ ،‬حيــث قمــت بشــرب املســكر ‪ ،‬وأنــا مســلم ‪ ،‬وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه الرابــع ‪...........‬عــن طريــق‬\n‫املترجــم ‪...........‬أجــاب بقولــه ‪ :‬صحيــح ‪ ،‬حيــث قمــت بشــرب املســكر‬\n‫‪ ،‬وأنــا هندوســي الديانــة ‪ ،‬هكــذا أجــاب كل واحــد منهــم بانفــراده‬\n‫‪،‬ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة مــن ضمنهــا محضــر‬\n‫االستشــمام واملــدون بحــق املدعــى عليــه الثالــث والرابــع ‪ ،‬واملــدون‬\n‫علــى لفــه رقــم(‪ )2‬صحيفــة رقــم(‪ ، )13‬ثــم جــرى االطــاع علــى اعتــراف‬\n‫املدعــى عليــه األول والثانــي ‪ ،‬واملــدون علــى لفــه رقــم(‪ )2‬صحيفــة رقــم‬\n‫(‪ ، )14،15‬ثــم جــرى االطــاع علــى الســجل اجلنائــي الصــادر بحــق‬\n‫املدعــى عليهــم واملتضمــن (عــدم وجــود ســوابق مســجله بحــق كل واحــد‬\n‫منهــم حتــى تاريخــه ) ‪ ،‬واملــدون علــى لفــه رقــم (‪،)12،13،14،15‬‬\n‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة واإلقــرار ‪ ،‬ونظــرا لقلــة‬\n‫الكميــة املصنعــة مــن قبــل املدعــى عليــه األول والثانــي ‪ ،‬وملــا جــاء يف‬\n‫أوراق املعاملــة ‪ ،‬وحيــث إن املدعــى عليــه الرابــع غيــر مســلم ‪ ،‬وحيــث‬\n‫قــرر جمهــور العلمــاء مــن احلنفيــة واملالكيــة والشــافعية ‪ ،‬وهــو الصحيــح‬\n‫عنــد احلنابلــة ‪ ،‬وعليــه جميــع األصحــاب كمــا قــرر ذلــك املــرداوي‬\n‫صاحــب اإلنصــاف ‪ »:‬انــه ال يقــام احلــد علــى غيــر املســلم « ينظــر ‪:‬‬\n‫املبســوط للسرخســي‪( :‬ج‪24‬ص‪ ،)31‬التــاج واإلكليــل للمــواق‪( :‬ج‪ 8‬ص‬\n\n\n                                                                                           ‫‪336‬‬\n\f      ‫‪ ، )433‬شــرح البهجــة لألنصــاري‪( :‬ج‪ 5‬ص ‪ )105‬اإلنصــاف للمــرداوي‬\n      ‫(ج‪ 10‬ص‪ )233،232‬قــال البهوتــي يف كشــاف القنــاع(ج‪6‬ص‪« :)178‬‬\n      ‫وال يحــد ذمــي وال مســتأمن بشــربه أي املســكر ولــو رضــي بحكمنــا‬\n      ‫ألنــه يعتقــد حلــه « لذلــك كلــه قــررت مــا يلــي‪ :‬أوالً‪ :‬ثبــت لــدي إدانــة‬\n      ‫املدعــى عليهمــا األول والثانــي بتصنيــع املســكر بقصــد الشــرب ‪،‬‬\n      ‫وبنــاء علــى ذلــك قــررت تعزيــر كل واحــد منهــا مبــا يلــي ‪:‬أ‪ -‬ســجن كل‬\n      ‫واحــد منهمــا أربعــة أشــهر ابتــداء مــن توقيــف كل واحــد منهمــا بهــذه‬\n      ‫القضيــة‪،‬ب‪ -‬جلــد كل واحــد منهمــا مائــة وثمانــن جلــدة مفرقــة علــى‬\n      ‫ثــاث دفعــات ‪ ،‬كل دفعــة ســتون جلــدة ‪ ،‬مابــن كل دفعــة وأخــرى‬\n      ‫ســبعة أيــام ‪،‬ج‪ -‬أخــذ التعهــد الشــديد علــى كل واحــد منهمــا بعــدم‬\n      ‫العــودة ملثــل هــذه األمــور ‪.‬ثانيــا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه الرابــع‬\n      ‫بشــربه للمســكر ‪ ،‬و بنــاء علــى ذلــك قــررت تعزيــره علــى ذلــك مبــا‬\n      ‫يلي‪:‬أ)جلــده خمســن جلــدة دفعــة واحــدة علــى مــأ مــن النــاس‪ .‬ب) أخــذ‬\n      ‫التعهــد الشــديد عليــه بعــدم العــودة ملثــل هــذه األمــور‪ .‬ثالثــا ‪:‬ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه الثالــث بشــربه للعــرق املســكر ‪،‬وبنــاء علــى ذلــك‬\n      ‫قــررت مــا يلــي ‪:‬أ‪ -‬جلــده ثمانــن جلــدة دفعــة واحــدة ‪ ،‬حــد املســكر‬\n      ‫علــى مــأ النــاس ‪،‬ب‪-‬أخــذ التعهــد الشــديد عليــه بعــدم العــودة ملثــل هــذه‬\n      ‫األمــور‪ .‬هــذا مــا ظهــر لــي وبــه حكمــت ‪ .‬كمــا أوصيــت بترحيلهــم إلــى‬\n      ‫بالدهــم بعــد انتهــاء محكوميتهــم بعــد أخــذ مــا لهــم ومــا عليهــم مــن‬\n      ‫حقــوق زجــر ًا لهــم وعبــر ًة لغيرهــم وبعرضــه علــى املدعــي العــام لــم يقنــع‬\n      ‫بــه وطلــب متييــزه بــدون الئحــة اعتراضيــة ‪ ،‬وبعرضــه علــى املدعــى عليــه‬\n      ‫األول عــن طريــق املترجــم ‪...........‬قنــع بــه‪ .‬وبعرضــه علــى املدعــى عليــه‬\n      ‫الثانــي عــن طريــق املترجــم ‪...........‬قنــع بــه وبعرضــه علــى املدعــى عليــه‬\n\n\n‫‪337‬‬\n\f‫الثالــث عــن طريــق املترجــم ‪...........‬قنــع بــه وبعرضــه علــى املدعــى عليــه‬\n‫الرابــع عــن طريــق املترجــم ‪...........‬قنــع بــه ‪ ،‬وعليــه جــرى التوقيــع‪ ،‬مت‬\n‫قفــل اجللســة يف متــام الســاعة التاســعة صباحــا مــن يــوم الثالثــاء املوافــق‬\n‫‪1434/7/11‬هــ‪،‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه أجمعــن‪ .‬احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة الثانيــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل برقــم ‪ 341650120‬وتاريــخ ‪1434/7/17‬هــ؛ واملقيــدة‬\n‫لدينــا برقــم ‪ 341650120‬وتاريــخ ‪1434/7/19‬هــ؛ املرفــق بهــا القــرار‬\n‫الشــرعي رقــم (‪ ) 34266037‬وتاريــخ ‪1434/7/11‬هــ؛ الصــادر مــن‬\n‫فضيلــة الشــيخ‪........... /‬رئيــس احملكمــة اجلزائيــة بحائــل؛ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد‪........... /‬هنــدي اجلنســية رخصــة إقامــة رقــم‬\n‫(‪َ )...........‬و ‪...........‬هنــدي اجلنســية رخصــة إقامــة رقم (‪َ )...........‬و ‪...........‬‬\n‫هنــدي اجلنســية رخصــة إقامــة رقــم (‪َ )...........‬و ‪...........‬هنــدي اجلنســية‬\n‫رخصــة إقامــة رقــم (‪)...........‬؛ التهامهــم بقضيــة تصنيــع مســكر‪ .‬وقــد‬\n‫تضمــن القــرار حكــم فضيلتــه بســجن املدعــى عليهــم وجلدهــم وأخــذ‬\n‫التعهــد عليهــم علــى النحــو املفصــل فيــه؛ وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة ‪ :‬جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه‬\n‫علــى املدعــى عليهــم مــن تعزيــر‪ .‬واهلل املوفــق؛ وصلــى اهلل وســلم علــى‬\n                                                                       ‫نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                               ‫‪338‬‬\n\f339\n\f340\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":332,"source_page_end":340,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bb7b4de9fddba39e169484c62b05432e99751dabf77c1f939f4b991750e05832","normalized_text_hash":"ef20f916af451b85ba0e392480c20bed31f799e954cec3dd7f31bbb2af86844d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p332-34266037"},{"id":"698c1a12-c39b-5199-8053-d2e0826ec7d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -حيازة مسكر -املرء مسؤول عما وجد يف حيازته -إدانة باحليازة املجردة -التعزير بالسجن واجللد -أخذ تعهد على املدعى عليه بأخذ احليطة وتفقد السيارة .","document_number":"3444894","case_number":"33230324","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"مسكر -حيازة مسكر -املرء مسؤول عما وجد يف حيازته -إدانة باحليازة املجردة -التعزير بالسجن واجللد -أخذ تعهد على املدعى عليه بأخذ احليطة وتفقد السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3444894 :‬تاريخه‪1434/2/24 :‬هـ‬\n                       ‫رقم الدعوى‪33230324 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34193868‬تاريخه‪1434/04/21 :‬هـ‬\n\n\n        ‫مســكر ‪ -‬حيــازة مســكر ‪ -‬املــرء مســؤول عمــا وجــد يف حيازتــه ‪ -‬إدانــة‬\n        ‫باحليــازة املجــردة ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬أخــذ تعهــد علــى‬\n                                 ‫املدعــى عليــه بأخــذ احليطــة وتفقــد الســيارة ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قال تعالى ‪( :‬قالوا جزاؤه من وجد يف رحله فهو جزاؤه) ‪.‬‬\n        ‫‪ -2‬قــال صلــى اهلل عليــه وســلم ( لعــن اهلل اخلمــر وشــاربها وبائعهــا‬\n             ‫ومبتاعهــا وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة إليــه ) ‪.‬‬\n\n\n\n\n        ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة املســكر بقصــد الشــرب‬\n        ‫وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬حيــث‬\n        ‫قبــض علــى املدعــى عليــه مــن قبــل دوريــة أمــن الطــرق حيــث كان‬\n        ‫يقــود ســيارة وبتفتيشــها مت العثــور علــى جــركل وقــارورة صغيــرة بهمــا‬\n        ‫مــادة ســائلة يحتمــل أن تكــون مــن اخلمــر‪ ،‬أثبــت التقريــر الكيميائــي‬\n        ‫الشــرعي إيجابيــة العينــة ملــادة الكحــول اإليثيلــي وصــادق املدعــى عليــه‬\n        ‫علــى حيــازة املســكر وأنكــر عالقتــه بهــا ومبــا أن املدعــى عليــه أقــر‬\n        ‫باحليــازة وأنكــر قصــده مــن ذلــك الشــرب‪ ،‬قــررت احملكمــة إثبــات‬\n        ‫إدانــة املدعــى عليــه بحيــازة املســكر حيــازة مجــردة واحلكــم بتعزيــره‬\n\n‫‪355‬‬\n\f‫لقــاء ذلــك بســجنه مــدة شــهر وجلــده عشــرين جلــدة دفعــة واحــدة وعــدم‬\n‫ثبــوت قصــد املدعــى عليــه بحيــازة الشــرب وأخــذ التعهــد علــى املدعــى‬\n‫عليــه بأخــذ احليطــة واحلــذر وتفقــد ســيارته ‪ ،‬قنــع املدعــى عليــه واعترض‬\n‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬     ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                  ‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 3716‬وتاريــخ ‪1433/03/30‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪33613482‬وتاريــخ ‪1433/04/03‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقم‪33230324‬وتاريــخ ‪1433/04/03‬ه ـ فتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫ا‬\n‫األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي‬\n‫‪ 25 ،.....‬عامـ ًا ‪ ،‬عاطــل عــن العمــل « ســعودي اجلنســية « مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬أوقــف بتاريــخ ‪1433 /2/7‬ه ـ وأفــرج عنــه بالكفالــة‬\n‫بتاريــخ ‪1433/2/8‬ه ـ يقيــم يف األحســاء حــي ‪ ......‬حيــث أنــه بتاريــخ‬\n‫‪ 1433 /2/7‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل رجــال دوريــات‬\n‫أمــن الطــرق مبحافظــة األحســاء وذلــك أثنــاء إقامــة نقطــة تفتيــش‬\n‫بالقــرب مــن شــركة ‪.....‬علــى طريــق األحســاء ‪ -‬الدمــام حيــث كان‬\n‫يقــود ســيارة مــن نــوع موديــل ( ‪ ) 2011‬اللــون أبيــض حتمــل اللوحــة رقــم‬\n\n                                                                                        ‫‪356‬‬\n\f      ‫( ‪ ).....‬وبتفتيــش الســيارة مت العثــور خلــف مقعــد الراكــب علــى جــركل‬\n      ‫ســع ( ‪ ) 2‬لتر بها الربع تقريب ًا من ســائل شــفاف عدمي اللون تنبعث منها‬\n      ‫رائحــة املســكر ‪ ،‬ومت العثــور بالقــرب مــن قــدم الســائق علــى قــارورة ماء‬\n      ‫صغيــرة احلجــم ســعة ( ‪ 350‬مــل ) مملــؤة ثالثــة أربــاع القــارورة مــن مــادة‬\n      ‫ســائلة مييــل لونهــا للذهبــي يحتمــل أن يكــون مــن اخلمر املســكر ‪ .‬وأثبت‬\n      ‫تقريــر الســموم الشــرعية رقــم ( ‪ /.....‬ســموم ومخــدرات ‪ ) 1433/‬لعــام‬\n      ‫‪1433‬ه ـ الصــادر مــن إدارة األدلــة اجلنائيــة باملنطقــة الشــرقية إيجابيــة‬\n      ‫العينــة املرســلة وهــي عبــارة عــن جــركل بالســتيكي كبيــر أبيــض‬\n      ‫اللــون بــه مــادة ســائلة عدميــة اللــون حجمهــا ( ‪ 300‬مــل ) ملــادة الكحــول‬\n      ‫( اإليثيلــي ) املســكرة بنســبة ( ‪ ، ) %33‬وإيجابيــة العينــة األخــرى وهــي‬\n      ‫عبــارة عــن عبــوة مــاء صحــة صغيــرة ســعة ( ‪ 330‬مــل ) بهــا مــادة صفــراء‬\n      ‫اللــون حجمهــا ( ‪ 80‬مــل ) ملــادة الكحــول ( اإليثيلــي ) املســكرة بنســبة‬\n      ‫( ‪ . ) %20‬وباســتجواب املدعــى عليــه أقــر بواقعــة القبــض عليــه ‪ .‬وقــد‬\n      ‫أســفر التحقيــق عــن توجيــه االتهــام لــه بحيــازة املســكر ( املوصوفــة يف‬\n                   ‫الدعــوى ) بقصــد الشــرب ؛ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ - 1‬أقوالــه املدونــة علــى الصفحــة رقــم ( ‪ ) 13‬مــن دفتــر التحقيــق لفــة‬\n                                                                              ‫رقــم ( ‪. ) 1‬‬\n                                     ‫‪ - 2‬محضر القبض املرفق على لفة رقم ( ‪. ) 2‬‬\n                         ‫‪ - 3‬تقرير السموم الشرعية املدون على لفة رقم ( ‪. ) 15‬‬\n      ‫‪ - 4‬محضــر استشــمام املضبوطــات املــدون علــى الصفحــة رقــم ( ‪ ) 8‬مــن‬\n      ‫دفتر التحقيق لفة رقم ( ‪ . ) 1‬وبالبحث عما إذا كان له سوابق مت العثور‬\n      ‫علــى ســابقة واحــدة وهــي الســلب والتهديــد بالســاح وهــروب وتغيــب ‪.‬‬\n      ‫وحيــث إن م ــا أق ــدم عليــه املدعــى عليــه وه ــو بكامــل أهليت ــه املعتبــرة‬\n\n\n‫‪357‬‬\n\f‫ش ــرع ًا فعــل مح ــرم ومعاقــب عليــه ش ـ ــرع ًا ؛ أطلــب إثبــات ما أســند إليه‪،‬‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه مــن اتهــام ‪ .‬هكــذا‬\n‫ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى‬\n‫ا ‪ :‬ماذكــره املدعــي‬        ‫عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n‫العــام مــن اتهامــي بحيــازة قــارورة مــاء صغيــرة احلجــم ســعة‪350‬مل مملــؤة‬\n‫ثالثــة أربــاع القــارورة مــن مــادة ســائلة مــن املســكر فصحيــح ولك َّنهــا‬\n‫ليســت لــي وإمنــا أنــا أشــتغل علــى ســيارتي وأنقــل ركاب ـ ًا فلعلهــا ألحــد‬\n‫الــركاب هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬\n‫ومنهــا تقريــر الســموم واملخــدرات رقــم ( ‪ ).....‬لعــام ‪1433‬ه ـ الصــادر‬\n‫مــن إدارة األدلــة اجلنائيــة باملنطقــة الشــرقية إيجابيــة العينــة املرســلة مــن‬\n‫الكميــة املضبوطــة ملــادة الكحــول اإليثيلــي املســكرة بنســبة ( ‪) % 33‬‬\n‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمنــة وجــود‬\n‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد‬     ‫ســابقة ســلب وتهديــد فبنـ ً‬\n‫أن املدعــى‬    ‫النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه ومبــا َّ‬\n‫عليــه أقـ َّـر بحيــازة قــارورة املســكر املوصوفــة أعــاه وأنكــر أن يكــون‬\n‫عمــا وجــد يف حيازتــه‬    ‫أن املــرء مســؤول َّ‬‫قصــده مــن ذلــك الشــرب ومبــا َّ‬\n‫أن مــا‬ ‫قــال تعالــى ‪ « :‬قالــوا جــزاؤه مــن وجــد يف رحلــه فهــو جــزاؤه » ومبــا َّ‬\n‫صــدر مــن املدعــى عليــه مــن احملــرم شــرع ًا قــال صلــى اهلل عليــه وســلم‬\n‫لعــن اهلل اخلمــر وشــرابها وبائعهــا ومبتاعهــا وعاصرهــا ومعتصرهــا‬\n‫وحاملهــا واحملمولــة إليــه ) ممــا يســتوجب تعزيــر املدعــى عليــه لــذا كلــه‬\n‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي‪ :‬أو ًال ‪ /‬ثبــت‬\n‫ـدي إدانــة املدعــى عليــه بحيــازة قــارورة مــاء صغيــرة احلجــم ســعة‪350‬مل‬     ‫لـ َّ‬\n‫مملــؤة ثالثــة أربــاع القــارورة مــن مــادة ســائلة مــن املســكر حيــازة مجردة‬\n\n\n                                                                                           ‫‪358‬‬\n\f      ‫وعزرتــه لقــاء ذلــك بســجنه ملــدة شــهر حتتســب منهــا املــدة التــي أوقــف‬\n      ‫فيهــا علــى ذمــة القضيــة وبجلــده عشــرون جلــدة دفعــة واحــدة ‪ .‬ثانيـ ًا ‪ /‬لــم‬\n      ‫ـدي أن قصــد املدعــى عليــه مــن هــذه احليــازة هــو الشــرب وقــررت‬     ‫يثبــت لـ َّ‬\n      ‫ر َّد دعــوى املدعــي العــام بإثبــات ذلــك ‪ .‬ثالثـ ًا ‪ /‬يؤخــذ عليــه التعهــد بأخــذ‬\n      ‫احليطــة واحلــذر وتفقــد ســيارته دائم ـ ًا ‪ .‬وبتــاوة احلكــم علــى الطرفــن‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب‬\n      ‫املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي‬\n      ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف‬\n                                                                         ‫‪1434/02/23‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n      ‫‪ 332265370‬وتاريــخ ‪1434/2/30‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪/34/563683‬ج‪ 1‬وتاريــخ ‪1434/3/4‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .....‬املســجل برقــم ‪3444894‬‬\n      ‫وتاريــخ ‪1434/2/24‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ .....‬يف قضيــة‬\n      ‫مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ؛ وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1434 /4/21‬ه ـ ‪.‬‬\n\n\n\n\n‫‪359‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":355,"source_page_end":359,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"74980ac3438851a8f0ec895949ad5fc51e3f72f4415fbc5ddc5aea576ee46598","normalized_text_hash":"cc28227a1571ae44407cd60814d532217c4fbdc06ee6643f4667d9bce91c80de","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p355-3444894"},{"id":"4df58c7e-8a9a-536a-adbd-e87ac64c4e9e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -حيازة مسكر بقصد الشرب -املشاركة يف حيازة املسكر بقصد الشرب -التستر على وجود املسكر -إقرار املدعى عليه - تعزير من جالس العصاة يف معصيتهم -التعزير باجللد علن ا حديث عائشة -رضي اهلل عنها -يف الصحيحن (يغزو جيش الكعبة فإذا كانوا ببيداء من األرض يخسف بأولهم وآخرهم) قالت :قلت: يا رسول اهلل كيف يخسف بأولهم وآخرهم وفيهم أسواقهم ومن ليس منهم؟ قال( :يخسف بأولهم وآخرهم ثم يبعثون على نياتهم).","document_number":"34175033","case_number":"34121383","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالدمام بكتاب فضيلة رئيسها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/14","year":"1434","subject":"مسكر -حيازة مسكر بقصد الشرب -املشاركة يف حيازة املسكر بقصد الشرب -التستر على وجود املسكر -إقرار املدعى عليه - تعزير من جالس العصاة يف معصيتهم -التعزير باجللد علن ا حديث عائشة -رضي اهلل عنها -يف الصحيحن (يغزو جيش الكعبة فإذا كانوا ببيداء من األرض يخسف بأولهم وآخرهم) قالت :قلت: يا رسول اهلل كيف يخسف بأولهم وآخرهم وفيهم أسواقهم ومن ليس منهم؟ قال( :يخسف بأولهم وآخرهم ثم يبعثون على نياتهم).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34175033:‬تاريخه‪ 1434/03/14 :‬هـ‬\n                   ‫رقم الدعوى ‪34121383 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34192840‬تاريخه‪1434/4/21:‬هـ‬\n\n\n    ‫مســكر ‪ -‬حيــازة مســكر بقصــد الشــرب ‪ -‬املشــاركة يف حيــازة املســكر‬\n    ‫بقصــد الشــرب‪ -‬التســتر علــى وجــود املســكر‪ -‬إقــرار املدعــى عليــه ‪-‬‬\n       ‫تعزيــر مــن جالــس العصــاة يف معصيتهــم‪ -‬التعزيــر باجللــد علن ـ ًا‬\n\n\n\n\n    ‫حديــث عائشــة ‪-‬رضــي اهلل عنهــا‪ -‬يف الصحيحــن (يغــزو جيــش الكعبــة‬\n    ‫فــإذا كانــوا ببيــداء مــن األرض يخســف بأولهــم وآخرهــم) قالــت‪ :‬قلــت‪:‬‬\n    ‫يــا رســول اهلل كيــف يخســف بأولهــم وآخرهــم وفيهــم أســواقهم ومــن‬\n    ‫ليــس منهــم؟ قــال‪( :‬يخســف بأولهــم وآخرهــم ثم يبعثون علــى نياتهم)‪.‬‬\n\n\n\n\n    ‫مت توجيــه االتهــام للمدعــى عليــه األول بحيازة املســكر بقصد الشــرب‪،‬‬\n    ‫واتهــام املدعــى عليهــم الثالثــة اآلخريــن بالتســتر علــى وجود املســكر مع‬\n    ‫املدعــى عليــه األول‪ ،‬وذلــك بعدمــا مت اســتيقاف املدعــى عليهــم األربعــة‬\n    ‫بعــد مشــاهدة الســيارة تســير عكــس الطريــق وهــي بقيــادة املدعــى‬\n    ‫عليــه الثانــي‪ ،‬وبتفتيشــها عثــر علــى علــب حتتــوي علــى املســكر‪ ،‬أثبــت‬\n    ‫التقريــر الكيمــاوي الشــرعي احتــواء العينــة ملــادة الكحــول اإليثيلــي‪،‬‬\n    ‫بعــرض دعــوى املدعــي العــام علــى املدعــى عليهــم أقــر املدعــى عليــه‬\n    ‫األول بشــراء املســكر لقصــد الشــرب‪ ،‬كمــا أقــر املدعــى عليــه الثانــي‬\n\n                                                                                     ‫‪366‬‬\n\f      ‫بإخفــاء املســكر يف ســيارته‪ ،‬كمــا أقــر املدعــى عليــه الثالــث بعلمــه‬\n      ‫بوجــود املســكر يف الســيارة بعــد ركوبــه ولــم ينكــر عليهــم ذلــك‪،‬‬\n      ‫كمــا أقــر املدعــى عليــه الرابــع بقصــد شــربه للمســكر‪ ،‬نظــر ًا إلقــرار‬\n      ‫املدعــى عليــه األول بشــراء املســكر لقصــد الشــرب وإلقــرار كل مــن‬\n      ‫املدعــى عليهمــا الثانــي والرابــع باملشــاركة يف احليــازة لقصــد الشــرب‬\n      ‫وإلقــرار املدعــى عليــه الثانــي بعلمــه بوجــود املســكر عنــد بقيــة املدعــى‬\n      ‫عليهــم بعــد ركوبــه معهــم وألنــه مت القبــض عليهــم قبل نزولــه منهم‪ ،‬وملا‬\n      ‫قــرره بعــض أهــل العلــم مــن تعزير من جالــس العصاة يف معصيتهم‪ ،‬وألن‬\n      ‫اإلقــرار حجــة علــى املقــر وال عــذر ملــن أقــر لــذا فقــد ثبــت شــراء املدعــى‬\n      ‫عليــه األول لعلــب املســكر املذكــورة يف الدعــوى وحيازتــه باملشــاركة‬\n      ‫رفــق كل مــن املدعــى عليهمــا الثانــي والرابــع لقصــد الشــرب‪ ،‬ومت‬\n      ‫احلكــم بتعزيــر املدعــى عليــه األول بجلــده خمســن جلــدة علنـ ًا وتعزيــر‬\n      ‫املدعــى عليهمــا الثانــي والرابــع بجلــد كل واحــد منهمــا أربعــن جلــدة‬\n      ‫علنـ ًا وتعزيــر املدعــى عليــه الثالــث خمــس عشــرة جلــدة‪ ،‬بعــرض احلكــم‬\n      ‫علــى املدعــي العــام واملدعــى عليهــم اعتــرض عليــه املدعــي العــام وطلــب‬\n      ‫اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه املدعــى عليهــم وبعــد‬\n                         ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم األحــد ‪1434/3/29‬ه ـ لــدي أنــا‬\n      ‫‪...‬القاضــي باحملكمــة اجلزئيــة بالقطيــف بنــاء علــى املعاملــة احملالــة إلــي‬\n      ‫مــن فضيلــة الرئيــس برقــم ‪ 34121383‬يف ‪1434/3/14‬ه ـ والــواردة‬\n      ‫بكتــاب رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة القطيــف‬\n‫‪367‬‬\n\f‫بكتابــه ذي الرقــم ه ق‪ 1773/2/4‬يف ‪1434/3/14‬ه عليــه افتتحــت‬\n‫اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي العــام ‪...‬مبوجــب‬\n‫كتاب التكليف رقم هـ ق ‪ 2156/2/4‬يف ‪1431/9/15‬هـ وادعى على‬\n‫احلاضــر معــه ‪.../1‬الســعودي بالســجل املدنــي رقــم ‪...‬و‪.../2‬الســعودي‬\n‫بالســجل املدنــي رقــم ‪...‬و‪.../3‬الســعودي بالســجل املدنــي رقــم ‪...‬و‪.../4‬‬\n‫ا يف دعــواه حيــث إنــه يف يــوم‬    ‫الســعودي بالســجل املدنــي رقــم ‪...‬قائ ـ ً‬\n‫الســبت املوافــق ‪1433/11/6‬ه ـ شــوهدت ســيارة نــوع ‪ ......‬حتمــل اللوحــة‬\n‫رقــم (‪ )...‬عكــس الطريــق ومت اســتيقافها وتبــن أنهــا بقيــادة الثانــي‬\n‫‪...‬وبتفتيــش املركبــة عثــر حتــت مرتبــة املرافــق األمامــي علــى ‪ 3‬علــب‬\n‫‪500‬مــل حتتــوي علــى املســكر‪ ،‬أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫الصــادر مــن املركــز االقليمــي ملراقبــة الســموم رقــم (‪232‬ك ش) وتاريخ‬\n‫‪1434/1/19‬ه ـ احتــواء العينــة املرســلة ملــادة الكحــول االيثيلــي وبنســبة‬\n‫مســكره‪ ،‬وبنــاء علــى مــا ذكــر أقــرر اتهــام املواطــن‪ ..../‬بحيــازة ‪3‬‬\n‫ثــاث علــب حتتــوي علــى املســكر ســعة الواحــدة منهــا (‪ )500‬مــل وذلــك‬\n‫بقصــد شــربها‪ ،‬وباتهــام كل مــن املواطــن‪ .../‬واملواطــن‪ ... /‬واملواطن‪.../‬‬\n‫بالتســتر علــى وجــود املســكر مــع املتهــم األول‪ ،‬وحيــث إن مــا أقدم عليه‬\n‫املذكوريــن وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم شــرع ًا‬\n‫ممــا يتعــن معــه إحالتهــم إلــى احملكمــة اجلزائيــة وفق ـاً(‪)128-126‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة إلثبــات مــا أســند إليهــم واحلكــم عليهــم‬\n‫بعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم هــذا مــا ادعــى بــه وبعرضــه‬\n‫ا‬ ‫علــى املدعــى عليهــم وبســؤالهم عنــه أجــاب املدعــى عليــه األول ‪ ...‬قائـ ً‬\n‫مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن اتهامــي بحيــازة ثــاث‬\n‫علــب مــن املســكر بالســعة التــي ذكــر لقصــد الشــرب فغيــر صحيــح‬\n\n\n                                                                                    ‫‪368‬‬\n\f      ‫والصحيــح أنــي قمــت بشــرائها لقصــد شــربها رفــق كل مــن ‪ ...‬و‪ ...‬وأمــا‬\n      ‫‪ ...‬فليــس لــه عالقــة يف أمــر الشــرب وقــد كانــت القواريــر يف الســيارة‬\n      ‫التــي تخــص ‪...‬وقــد أخفاهــا حتــت مرتبتــه إذ كان قائــد الســيارة إال‬\n      ‫أننــا لــم نشــرب منهــا شــيئ ًا هــذا مــا أجــاب بــه وأجــاب املدعــى عليــه‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن تســتري فغيــر‬          ‫‪...‬قائ ـ ً‬\n      ‫صحيــح والصحيــح أن املســكر كان معــي يف الســيارة وقــد أخفيتــه‬\n      ‫حتــت مرتبتــي وقــد اشــتراه ‪...‬لنشــربه إال أننــا لــم نقــم بشــربه هــذا مــا‬\n      ‫ا مــا ذكــره املدعــي العــام‬ ‫أجــاب بــه وأجــاب املدعــى عليــه الثالــث ‪...‬قائـ ً‬\n      ‫مــن تســتري علــى املدعــى عليهــم غيــر صحيــح والصحيــح أنهــم مــروا بــي‬\n      ‫كونهــم زمالئــي لينزلونــي عنــد ســيارتي وبعــد ركوبــي معهــم علمــت‬\n      ‫بوجــود املســكر معهــم ولــم أعلــم بوجــوده قبــل ركوبــي وقبــض علينــا‬\n      ‫قبــل أن أنــزل مــن الســيارة هــذا مــا أجــاب بــه وأجــاب املدعــى عليــه الرابــع‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن تســتري غيــر‬          ‫‪ ...‬قائ ـ ً‬\n      ‫صحيــح والصحيــح أن املدعــى عليــه ‪...‬قــد اشــترى العلــب املذكــورة مــن‬\n      ‫املســكر لنشــربها جميع ـ ًا وأمــا املدعــى عليــه ‪ ...‬فليــس لــه عالقــة وقــد‬\n      ‫كانــت العلــب يف الســيارة التــي كنــت مــع زمالئــي فيهــا هــذا مــا أجــاب‬\n      ‫بــه وبســؤال املدعــى عليــه ‪...‬هــل قــام باإلنــكار علــى املدعــى عليهــم‬\n      ‫ا إننــي لــم أقــم مبــا ذكــر‬\n                                    ‫عنــد علمــه بوجــود املســكر معهــم أجــاب قائـ ً‬\n      ‫هــذا مــا أجــاب بــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار‬\n      ‫املدعــى عليــه ‪...‬بشــراء املســكر لقصــد الشــرب وإلقــرار كل مــن‬\n      ‫املدعــى عليــه ‪ .....‬و‪ ......‬باملشــاركة يف احليــازة لقصــد الشــرب وإلقــرار‬\n      ‫املدعــى عليــه ‪...‬بعلمــه بوجــود املســكر عنــد بقيــة املدعــى عليهــم بعــد‬\n      ‫ركوبــه معهــم وألنــه مت القبــض عليهــم قبــل نزولــه منهــم وحلديــث عائشــة‬\n\n\n‫‪369‬‬\n\f‫رضــي اهلل عنهــا يف الصحيحــن (يغــزو جيــش الكعبــة فــإذا كانــوا‬\n‫ببيــداء مــن األرض يخســف بأولهــم وآخرهــم) قالــت قلــت يــا رســول اهلل‬\n‫كيــف يخســف بأولهــم وآخرهــم وفيهــم أســواقهم ومــن ليــس منهــم قــال‬\n‫(يخســف بأولهــم وآخرهــم ثــم يبعثــون علــى نياتهــم) وملــا قــرره بعــض أهــل‬\n‫العلــم مــن تعزيــر مــن جالــس العصــاة يف معصيتهــم لــذا فقــد ثبــت لــدي‬\n‫شــراء املدعــى عليــه ‪...‬لعلــب املســكر املذكــورة يف الدعــوى وحيازتــه‬\n‫باملشــاركة رفــق كل مــن املدعــى عليــه ‪ ......‬واملدعــى عليــه ‪...‬لقصــد‬\n‫الشــرب وقــررت أو ًال تعزيــر املدعــى عليــه ‪ ...‬بجلــده خمســن جلــدة دفعــة‬\n‫واحــدة ثاني ـ ًا تعزيــر كل واحــد مــن املدعــى عليهمــا ‪...‬و‪...‬بجلــد كل‬\n‫واحــد منهمــا أربعــن جلــدة ثالثـ ًا تعزيــر املدعى عليه بجلده خمس عشــرة‬\n‫جلــدة ‪ ...‬ومبــا ذكــر حكمــت وأفهمــت املدعــى عليــه ‪...‬بــأن كان عليــه‬\n‫أن ينكــر علــى مــن كان مبعيتــه حيازتهــم للمســكر لقصــد الشــرب‬\n‫ففهمــه وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم اعتــرض‬\n‫عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع‬\n‫بــه املدعــى عليهــم وســيتم بعــث كامــل املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم حســب املتبــع واختتمــت اجللســة الســاعة احلاديــة عشــر‬\n‫والنصــف وللبيــان حــرر يف ‪1434/3/29‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬احلمــد هلل وحــده وبعــد لقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف بالدمــام بكتــاب فضيلــة رئيســها‬\n‫رقــم ‪ 341326522‬يف ‪1434/6/13‬ه ـ املقيــدة يف هــذه احملكمــة برقــم‬\n‫‪ 341326522‬يف ‪1434/6/17‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقها‬\n‫إعــام احلكــم الصــادر منــي برقــم ‪ 34175033‬يف ‪1434/3/29‬ه ـ‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم‬\n\n\n                                                                                    ‫‪370‬‬\n\f      ‫‪ 34231870‬يف ‪1434/6/5‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n      ‫علــى قرارنــا رقــم ‪/34192840‬ج‪/2‬ب وتاريــخ ‪1434/4/21‬ه ـ قررنــا‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/6/5‬ه ـ قاضــي اســتئناف ‪...‬ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ‪......‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه‬\n      ‫وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف ‪1434/6/18‬ه ـ وصلــى اهلل وســلم علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n‫‪371‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":366,"source_page_end":371,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"68a2aeec79fb9b42bea6365349e1627647888bb14c696d2f20fbc4b014400ff2","normalized_text_hash":"6ea9c9736194bd256f7e08331724069a200b7bbfc274e6330a1fadcf43912516","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p366-34175033"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

